const APSTAT_BANK = [
  {
    key: "apstat-u1", label: "U1: Exploring One-Variable Data", icon: "📊", color: "#0369a1", bg: "#f0f9ff",
    questions: [
      { id:"u1q1", q:"A researcher records the eye color of each participant in a study. What type of variable is eye color?", choices:{A:"A parameter", B:"Categorical", C:"Quantitative discrete", D:"Quantitative continuous"}, answer:"B", explanation:"Eye color places each individual into a group/category and has no numerical meaning, so it is categorical." },
      { id:"u1q2", q:"Which of the following is a quantitative variable?", choices:{A:"Type of car a person drives", B:"Number of siblings a student has", C:"Zip code of a residence", D:"Jersey number on a soccer team"}, answer:"B", explanation:"Number of siblings is a count you can do arithmetic on. Jersey numbers and zip codes are labels, not measurements, so they are categorical despite using digits." },
      { id:"u1q3", q:"A variable that can take any value in an interval, such as the exact height of a tree, is best described as:", choices:{A:"Ordinal categorical", B:"Quantitative continuous", C:"Categorical", D:"Quantitative discrete"}, answer:"B", explanation:"Continuous quantitative variables can take any value within an interval, including fractional values. Heights and weights are classic examples." },
      { id:"u1q4", q:"The number of cars passing through an intersection in one hour is recorded each day. This variable is:", choices:{A:"Categorical ordinal", B:"Quantitative continuous", C:"Categorical nominal", D:"Quantitative discrete"}, answer:"D", explanation:"A count of cars takes only whole-number values, which makes it quantitative discrete." },
      { id:"u1q5", q:"Students rate a movie as 'poor', 'fair', 'good', or 'excellent'. This variable is:", choices:{A:"Quantitative discrete", B:"Quantitative continuous", C:"Categorical with a natural order", D:"Neither categorical nor quantitative"}, answer:"C", explanation:"The ratings sort individuals into categories that have a meaningful order, so it is categorical (ordinal) — not quantitative, since the gaps between ratings are not measured numbers." },
      { id:"u1q6", q:"A histogram of house prices has a long tail stretching to the right toward a few very expensive homes. The distribution is best described as:", choices:{A:"Uniform", B:"Skewed left", C:"Skewed right", D:"Symmetric"}, answer:"C", explanation:"The tail points toward the larger values on the right, so the distribution is skewed right (positively skewed)." },
      { id:"u1q7", q:"Which graphical display is most appropriate for showing the distribution of a single categorical variable?", choices:{A:"Stemplot", B:"Bar chart", C:"Histogram", D:"Boxplot"}, answer:"B", explanation:"Bar charts display frequencies or relative frequencies of categories. Histograms, boxplots, and stemplots are for quantitative data." },
      { id:"u1q8", q:"A stemplot is generally most useful when:", choices:{A:"You want to compare more than five groups at once", B:"The variable is categorical", C:"The data set is small to moderate and you want to keep the actual values", D:"The data set is very large (thousands of values)"}, answer:"C", explanation:"Stemplots preserve individual data values and work well for small-to-moderate quantitative data sets, but become unwieldy for very large ones." },
      { id:"u1q9", q:"In a dotplot, what does a single dot represent?", choices:{A:"The mean of the data", B:"One individual observation at that value", C:"A category label", D:"The total count of all observations"}, answer:"B", explanation:"Each dot stands for one observation located at its value on the number line; stacked dots show repeated values." },
      { id:"u1q10", q:"A boxplot shows the median much closer to Q1 than to Q3, with a long whisker on the high end. This suggests the distribution is:", choices:{A:"Skewed right", B:"Symmetric", C:"Bimodal", D:"Skewed left"}, answer:"A", explanation:"When the median sits near Q1 and the upper whisker is long, the larger values are more spread out, indicating right skew." },
      { id:"u1q11", q:"Which display would best reveal a gap or cluster in a quantitative distribution?", choices:{A:"A histogram or dotplot", B:"A two-way table", C:"A bar chart of categories", D:"A pie chart"}, answer:"A", explanation:"Histograms and dotplots show the full shape of quantitative data, making gaps, clusters, and outliers visible. Pie and bar charts are for categorical data." },
      { id:"u1q12", q:"A distribution that has two distinct peaks is described as:", choices:{A:"Uniform", B:"Bimodal", C:"Skewed", D:"Symmetric"}, answer:"B", explanation:"Two clear peaks indicate a bimodal distribution, often a sign of two subgroups within the data." },
      { id:"u1q13", q:"Relative frequency in a frequency table is computed as:", choices:{A:"The cumulative count up to that category", B:"Category count divided by the total count", C:"Category count minus the total", D:"The total divided by the number of categories"}, answer:"B", explanation:"Relative frequency = (count in category) / (total count), expressing each category as a proportion of the whole." },
      { id:"u1q14", q:"A survey of 200 students records favorite subject: Math 60, Science 50, English 40, History 50. What relative frequency (percent) chose Science?", choices:{A:"50%", B:"10%", C:"20%", D:"25%"}, answer:"D", explanation:"50/200 = 0.25 = 25%." },
      { id:"u1q15", q:"When a distribution is strongly skewed right, which is generally true?", choices:{A:"Mean < Median", B:"Mean > Median", C:"Mean = Median", D:"The mode equals the mean"}, answer:"B", explanation:"In a right-skewed distribution the large values in the tail pull the mean above the median." },
      { id:"u1q16", q:"Which measure of center is most resistant to outliers?", choices:{A:"Mean", B:"Range", C:"Median", D:"Standard deviation"}, answer:"C", explanation:"The median depends only on the middle position, so extreme values barely affect it. The mean, range, and standard deviation are all sensitive to outliers." },
      { id:"u1q17", q:"For a roughly symmetric distribution with no outliers, the most appropriate measures of center and spread are:", choices:{A:"Mean and standard deviation", B:"Mode and range", C:"Median and range", D:"Median and IQR"}, answer:"A", explanation:"For symmetric data without outliers, the mean and standard deviation summarize center and spread well. Median/IQR are preferred when the data are skewed or have outliers." },
      { id:"u1q18", q:"'SOCS' is a reminder to describe a distribution using:", choices:{A:"Sum, order, central, standardize", B:"Slope, origin, correlation, scatter", C:"Sample, observation, count, statistic", D:"Shape, outliers, center, spread"}, answer:"D", explanation:"SOCS = Shape, Outliers, Center, Spread — the four features used to describe a one-variable distribution." },
      { id:"u1q19", q:"Two data sets have the same mean but Set A has a larger standard deviation than Set B. This means:", choices:{A:"Set A has a higher center", B:"Set B contains an outlier", C:"Set A's values are more spread out from the mean", D:"Set A is skewed and Set B is symmetric"}, answer:"C", explanation:"A larger standard deviation means the observations are, on average, farther from the mean — i.e., more spread. It says nothing directly about center or skew." },
      { id:"u1q20", q:"Find the mean of the data set: [4, 8, 15, 16, 23, 42].", choices:{A:"15.5", B:"21.5", C:"16.0", D:"18.0"}, answer:"D", explanation:"Sum = 108, divided by 6 = 18.0." },
      { id:"u1q21", q:"Find the median of: [7, 3, 9, 5, 12, 8, 6].", choices:{A:"6", B:"8", C:"7", D:"9"}, answer:"C", explanation:"Sorted: [3, 5, 6, 7, 8, 9, 12]. With 7 values the median is the 4th value, 7." },
      { id:"u1q22", q:"Find the mode of: [10, 12, 12, 14, 16, 16, 16, 20].", choices:{A:"12", B:"20", C:"16", D:"14"}, answer:"C", explanation:"16 appears three times, more than any other value, so it is the mode." },
      { id:"u1q23", q:"For the data [2, 4, 6, 8, 100], which statement is correct?", choices:{A:"Both equal 6", B:"Mean = Median", C:"Median is larger than the mean", D:"Mean is much larger than the median due to the value 100"}, answer:"D", explanation:"Median = 6 but mean = 24 because 100 inflates the mean. This shows the mean's sensitivity to outliers." },
      { id:"u1q24", q:"Adding one new value equal to the current mean of a data set will:", choices:{A:"Always change the median to that value", B:"Leave the mean unchanged", C:"Increase the mean", D:"Decrease the mean"}, answer:"B", explanation:"Inserting a value exactly equal to the mean does not change the total balance point, so the mean stays the same." },
      { id:"u1q25", q:"Find the median of the even-sized set: [20, 22, 24, 26].", choices:{A:"25", B:"24", C:"22", D:"23"}, answer:"D", explanation:"With 4 values, average the 2nd and 3rd: (22+24)/2 = 23.0." },
      { id:"u1q26", q:"For [1, 3, 5, 7, 9, 11, 13, 15], find Q1.", choices:{A:"3", B:"5", C:"4", D:"7"}, answer:"C", explanation:"Lower half is [1, 3, 5, 7]; its median is (3+5)/2 = 4.0." },
      { id:"u1q27", q:"For the same data [1, 3, 5, 7, 9, 11, 13, 15], find the IQR.", choices:{A:"10", B:"8", C:"12", D:"6"}, answer:"B", explanation:"Q1 = 4.0, Q3 = 12.0, so IQR = Q3 - Q1 = 8.0." },
      { id:"u1q28", q:"For [12, 15, 15, 18, 20, 22, 25, 28, 30] (n=9), find Q3.", choices:{A:"22", B:"26.5", C:"28", D:"25"}, answer:"B", explanation:"Exclude the overall median (20). Upper half is [22, 25, 28, 30]; its median is (25+28)/2 = 26.5." },
      { id:"u1q29", q:"The IQR measures:", choices:{A:"The most common value", B:"The average distance from the mean", C:"The spread of the middle 50% of the data", D:"The full range of the data"}, answer:"C", explanation:"IQR = Q3 - Q1 captures the range of the central 50% of observations and is resistant to outliers." },
      { id:"u1q30", q:"What is the IQR of [5, 5, 5, 5, 5]?", choices:{A:"5", B:"0", C:"1", D:"Cannot be determined"}, answer:"B", explanation:"All values are identical, so Q1 = Q3 = 5 and IQR = 0." },
      { id:"u1q31", q:"The population standard deviation of [2, 4, 4, 4, 5, 5, 7, 9] is closest to:", choices:{A:"2.0", B:"2.5", C:"1.5", D:"3.0"}, answer:"A", explanation:"The mean is 5.0; the population standard deviation works out to about 2.00." },
      { id:"u1q32", q:"Find the range of [3, 7, 7, 19].", choices:{A:"16", B:"12", C:"19", D:"7"}, answer:"A", explanation:"Range = max - min = 19 - 3 = 16." },
      { id:"u1q33", q:"If every value in a data set is the same number, the standard deviation is:", choices:{A:"Equal to that number", B:"Equal to the mean", C:"Undefined", D:"Zero"}, answer:"D", explanation:"With no variability, every deviation from the mean is 0, so the standard deviation is 0." },
      { id:"u1q34", q:"Variance is best described as:", choices:{A:"The average squared deviation from the mean", B:"The square root of the standard deviation", C:"The difference between Q3 and Q1", D:"The middle value of the data"}, answer:"A", explanation:"Variance is the mean of the squared deviations from the mean; the standard deviation is its square root." },
      { id:"u1q35", q:"Using the 1.5×IQR rule on [10, 12, 13, 14, 15, 16, 18, 40], the upper outlier boundary is:", choices:{A:"21.5", B:"28.0", C:"23.75", D:"26.5"}, answer:"C", explanation:"Q1=12.5, Q3=17.0, IQR=4.5. Upper fence = Q3 + 1.5·IQR = 17.0 + 6.75 = 23.75." },
      { id:"u1q36", q:"In that same data set [10, 12, 13, 14, 15, 16, 18, 40], which value is flagged as a high outlier?", choices:{A:"18", B:"16", C:"40", D:"None of the values"}, answer:"C", explanation:"40 exceeds the upper fence of 26.5, so it is an outlier by the 1.5×IQR rule." },
      { id:"u1q37", q:"The 1.5×IQR rule is used to:", choices:{A:"Identify potential outliers", B:"Compute the standard deviation", C:"Find the mean", D:"Build a histogram"}, answer:"A", explanation:"Values below Q1 - 1.5·IQR or above Q3 + 1.5·IQR are flagged as potential outliers." },
      { id:"u1q38", q:"For [20, 21, 22, 23, 24, 25, 26], the lower outlier boundary (Q1 - 1.5·IQR) equals:", choices:{A:"19.0", B:"18.0", C:"17.0", D:"15.0"}, answer:"D", explanation:"Q1=21, Q3=25, IQR=4. Lower fence = 21 - 1.5·4 = 15.0." },
      { id:"u1q39", q:"A student's exam score is at the 80th percentile. This means:", choices:{A:"80% of students scored at or below this student", B:"The student scored 80%", C:"The student scored higher than 80 points", D:"80 students took the exam"}, answer:"A", explanation:"A percentile gives the percent of the distribution at or below a value; the 80th percentile means about 80% scored at or below that student." },
      { id:"u1q40", q:"On a test with mean 70 and standard deviation 10, a score of 85 has a z-score of:", choices:{A:"1.5", B:"2.0", C:"1.0", D:"0.85"}, answer:"A", explanation:"z = (85 - 70)/10 = 1.5." },
      { id:"u1q41", q:"A value of 48 comes from a distribution with mean 60 and SD 8. Its z-score is:", choices:{A:"-1.0", B:"1.5", C:"-0.5", D:"-1.5"}, answer:"D", explanation:"z = (48 - 60)/8 = -1.5." },
      { id:"u1q42", q:"A z-score of 0 means the observation is:", choices:{A:"The smallest value", B:"An outlier", C:"Equal to the mean", D:"At the median"}, answer:"C", explanation:"z = 0 occurs exactly when the value equals the mean, since z = (x - mean)/SD." },
      { id:"u1q43", q:"A distribution has mean 50 and SD 6. A value with z-score +2 equals:", choices:{A:"56", B:"58", C:"60", D:"62"}, answer:"D", explanation:"x = mean + z·SD = 50 + 2·6 = 62." },
      { id:"u1q44", q:"Every value in a data set is increased by 5. Which is unchanged?", choices:{A:"The maximum", B:"The median", C:"The mean", D:"The standard deviation"}, answer:"D", explanation:"Adding a constant shifts all measures of center and position up by 5 but does not change spread, so the standard deviation (and IQR and range) stay the same." },
      { id:"u1q45", q:"Every value in a data set is multiplied by 3. The new standard deviation is:", choices:{A:"Unchanged", B:"3 times the original", C:"9 times the original", D:"1/3 of the original"}, answer:"B", explanation:"Multiplying every value by a constant k multiplies measures of spread (SD, IQR, range) by |k|, so the SD becomes 3 times as large." },
      { id:"u1q46", q:"A data set has mean 10. If each value is transformed by y = 3x + 2, the new mean is:", choices:{A:"30", B:"23", C:"32", D:"12"}, answer:"C", explanation:"New mean = 3·(old mean) + 2 = 3·10 + 2 = 32." },
      { id:"u1q47", q:"Converting temperatures from Celsius to Fahrenheit (F = 1.8C + 32) will:", choices:{A:"Multiply the standard deviation by 1.8 and add 32", B:"Leave the standard deviation unchanged", C:"Add 32 to the standard deviation", D:"Multiply the standard deviation by 1.8"}, answer:"D", explanation:"Only the multiplier 1.8 affects spread; the +32 shift does not. So SD is multiplied by 1.8." },
      { id:"u1q48", q:"For a normal distribution, approximately what percent of data lies within 1 standard deviation of the mean?", choices:{A:"50%", B:"68%", C:"95%", D:"99.7%"}, answer:"B", explanation:"By the empirical (68-95-99.7) rule, about 68% of observations fall within 1 SD of the mean." },
      { id:"u1q49", q:"Heights are approximately normal with mean 68 in and SD 3 in. About 95% of heights fall between:", choices:{A:"59 and 77 in", B:"62 and 74 in", C:"65 and 71 in", D:"68 and 74 in"}, answer:"B", explanation:"95% lies within 2 SD: 68 ± 2·3 = 68 ± 6, i.e., 62 to 74 inches." },
      { id:"u1q50", q:"In a normal distribution, the mean, median, and mode are:", choices:{A:"Always 0", B:"All different", C:"All approximately equal", D:"Impossible to determine"}, answer:"C", explanation:"A normal distribution is symmetric and unimodal, so its mean, median, and mode coincide at the center." },
    ]
  },
  {
    key: "apstat-u2", label: "U2: Exploring Two-Variable Data", icon: "📈", color: "#0d9488", bg: "#f0fdfa",
    questions: [
      { id:"u2q1", q:"On a scatterplot, the explanatory variable is plotted on the:", choices:{A:"y-axis", B:"either axis, it does not matter", C:"x-axis", D:"diagonal"}, answer:"C", explanation:"By convention the explanatory (independent) variable goes on the x-axis and the response on the y-axis." },
      { id:"u2q2", q:"Two variables have a correlation of r = -0.92. This indicates:", choices:{A:"A strong negative linear relationship", B:"No relationship", C:"A strong positive linear relationship", D:"A weak positive linear relationship"}, answer:"A", explanation:"r close to -1 means a strong negative linear association: as one variable increases, the other tends to decrease." },
      { id:"u2q3", q:"Which value of r indicates the strongest linear relationship?", choices:{A:"0.30", B:"0.50", C:"-0.10", D:"-0.85"}, answer:"D", explanation:"Strength depends on |r|. |-0.85| = 0.85 is the largest, so it is the strongest, regardless of sign." },
      { id:"u2q4", q:"A correlation of r = 0 between two quantitative variables means:", choices:{A:"The variables are identical", B:"One variable causes the other", C:"There is no relationship of any kind", D:"There is no linear relationship, though a curved one may exist"}, answer:"D", explanation:"r measures only linear association. r = 0 rules out a linear trend but a strong nonlinear (e.g., curved) pattern can still be present." },
      { id:"u2q5", q:"The correlation coefficient r has which property?", choices:{A:"It can exceed 1 for strong relationships", B:"It is always between -1 and 1", C:"It changes if you swap x and y", D:"It has the same units as x"}, answer:"B", explanation:"r is unitless and always satisfies -1 ≤ r ≤ 1; it is also unchanged if x and y are swapped." },
      { id:"u2q6", q:"Correlation does not imply causation primarily because:", choices:{A:"scatterplots cannot show causation", B:"a lurking variable may explain the association", C:"r only works for categorical data", D:"r is always negative"}, answer:"B", explanation:"An observed association can be driven by a confounding/lurking variable, so correlation alone cannot establish that one variable causes the other." },
      { id:"u2q7", q:"A least-squares regression line is ŷ = 3 + 2x. The slope tells us that:", choices:{A:"y increases by 3 for each unit of x", B:"y is 3 when x is 0", C:"for each 1-unit increase in x, predicted y increases by 2", D:"the correlation is 2"}, answer:"C", explanation:"The slope 2 is the predicted change in y per one-unit increase in x." },
      { id:"u2q8", q:"For ŷ = 3 + 2x, the predicted value of y when x = 5 is:", choices:{A:"13", B:"10", C:"15", D:"11"}, answer:"A", explanation:"ŷ = 3 + 2(5) = 13." },
      { id:"u2q9", q:"In the model ŷ = 50 - 4x, the y-intercept 50 represents:", choices:{A:"the correlation", B:"the slope of the line", C:"the predicted y when x = 0", D:"the maximum value of y"}, answer:"C", explanation:"The intercept is the predicted response when the explanatory variable equals 0." },
      { id:"u2q10", q:"A residual is calculated as:", choices:{A:"predicted y minus observed y", B:"observed x minus predicted x", C:"the slope times x", D:"observed y minus predicted y"}, answer:"D", explanation:"Residual = observed - predicted (y - ŷ). A positive residual means the point lies above the line." },
      { id:"u2q11", q:"A data point lies below the regression line. Its residual is:", choices:{A:"negative", B:"positive", C:"undefined", D:"zero"}, answer:"A", explanation:"Below the line means observed y is less than predicted y, so y - ŷ is negative." },
      { id:"u2q12", q:"The least-squares regression line minimizes:", choices:{A:"the maximum residual", B:"the correlation", C:"the sum of the residuals", D:"the sum of the squared residuals"}, answer:"D", explanation:"'Least squares' refers to minimizing the sum of squared residuals." },
      { id:"u2q13", q:"A regression has r = 0.8, s_y = 4, s_x = 2. The slope of the LSRL is:", choices:{A:"2.0", B:"1.6", C:"0.4", D:"3.2"}, answer:"B", explanation:"slope = r·(s_y/s_x) = 0.8·(4/2) = 1.6." },
      { id:"u2q14", q:"The least-squares regression line always passes through the point:", choices:{A:"the largest data point", B:"(median x, median y)", C:"(0, 0)", D:"(x̄, ȳ), the means of the two variables"}, answer:"D", explanation:"Every LSRL passes through (x̄, ȳ)." },
      { id:"u2q15", q:"If r = 0.6, then r² equals:", choices:{A:"0.12", B:"0.77", C:"0.36", D:"0.60"}, answer:"C", explanation:"r² = 0.6² = 0.36." },
      { id:"u2q16", q:"An r² value of 0.81 is interpreted as:", choices:{A:"81% of points lie on the line", B:"the slope is 0.81", C:"the correlation is 0.81", D:"81% of the variation in y is explained by the linear model"}, answer:"D", explanation:"r² (the coefficient of determination) gives the proportion of variation in the response explained by the linear relationship with x." },
      { id:"u2q17", q:"If r² = 0.49, the correlation r could be:", choices:{A:"0.24", B:"only 0.70", C:"0.49", D:"0.70 or -0.70"}, answer:"D", explanation:"r = ±√0.49 = ±0.70; the sign matches the slope's direction, so both are possible." },
      { id:"u2q18", q:"A higher r² indicates:", choices:{A:"a steeper slope", B:"a stronger linear fit, with more variation explained", C:"more outliers", D:"a weaker linear fit"}, answer:"B", explanation:"Larger r² means the line explains more of the response's variation, i.e., a better linear fit." },
      { id:"u2q19", q:"Which is true about r² compared to r?", choices:{A:"r² is always between 0 and 1", B:"r² equals r", C:"r² has the same sign as the slope", D:"r² can be negative"}, answer:"A", explanation:"Because it is a square, r² ranges from 0 to 1 and is never negative; r carries the sign." },
      { id:"u2q20", q:"A residual plot that shows a clear curved pattern suggests:", choices:{A:"a linear model may not be appropriate", B:"a linear model is appropriate", C:"there are no outliers", D:"r = 1"}, answer:"A", explanation:"A good linear fit leaves residuals with no pattern. A curve in the residual plot signals the relationship is nonlinear." },
      { id:"u2q21", q:"An ideal residual plot for a good linear fit shows:", choices:{A:"a clear upward trend", B:"a random scatter around zero with no pattern", C:"all residuals equal to zero", D:"a U-shape"}, answer:"B", explanation:"Random scatter about the horizontal zero line indicates the linear model fits well." },
      { id:"u2q22", q:"Using a regression line to predict far outside the range of the observed x-values is called:", choices:{A:"interpolation", B:"correlation", C:"extrapolation", D:"standardizing"}, answer:"C", explanation:"Extrapolation is prediction beyond the observed x-range and can be unreliable." },
      { id:"u2q23", q:"An influential point in regression is one that:", choices:{A:"lies exactly on the line", B:"substantially changes the slope or position of the line if removed", C:"is always near the mean of x", D:"always has a residual of zero"}, answer:"B", explanation:"Influential points, often with extreme x-values, can markedly change the regression line when added or removed." },
      { id:"u2q24", q:"A point with a large residual is best described as:", choices:{A:"always an influential point", B:"a lurking variable", C:"an outlier in the regression", D:"the y-intercept"}, answer:"C", explanation:"A large residual marks a point far from the line in the y-direction — an outlier in the regression sense (not necessarily influential)." },
      { id:"u2q25", q:"Removing a high-leverage point far to the right in x causes the slope to change a lot. That point is:", choices:{A:"unrelated to the fit", B:"influential", C:"a residual", D:"a lurking variable"}, answer:"B", explanation:"If deleting it noticeably changes the slope, the point is influential." },
      { id:"u2q26", q:"In a two-way table, a marginal distribution refers to:", choices:{A:"the counts in the interior cells", B:"the conditional percentages", C:"the totals in the margins for one variable", D:"the grand total only"}, answer:"C", explanation:"Marginal distributions are the row or column totals describing one variable alone, ignoring the other." },
      { id:"u2q27", q:"A conditional distribution describes:", choices:{A:"the grand total", B:"the overall totals", C:"one variable's distribution within a fixed category of the other", D:"the correlation between the variables"}, answer:"C", explanation:"A conditional distribution restricts to one category of a variable and looks at the distribution of the other within it." },
      { id:"u2q28", q:"Of 100 surveyed, 70 said 'Yes'. The marginal relative frequency of 'Yes' is:", choices:{A:"30%", B:"50%", C:"70%", D:"35%"}, answer:"C", explanation:"70/100 = 70%." },
      { id:"u2q29", q:"Among 50 males, 30 said 'Yes'. The conditional proportion of 'Yes' given male is:", choices:{A:"0.60", B:"0.70", C:"0.50", D:"0.30"}, answer:"A", explanation:"30/50 = 0.60." },
      { id:"u2q30", q:"Two categorical variables are associated when:", choices:{A:"the conditional distributions differ across categories", B:"every cell has the same count", C:"the table is square", D:"the marginal totals are equal"}, answer:"A", explanation:"If the conditional distributions of one variable change across categories of the other, the variables are associated." },
      { id:"u2q31", q:"A segmented (stacked) bar chart is used to compare:", choices:{A:"two quantitative variables", B:"correlation", C:"residuals", D:"conditional distributions of a categorical variable across groups"}, answer:"D", explanation:"Segmented bar charts display conditional distributions, making category comparisons across groups easy." },
      { id:"u2q32", q:"A class has 12 boys and 8 girls; 9 boys and 2 girls play a sport. What percent of boys play a sport?", choices:{A:"55%", B:"45%", C:"25%", D:"75%"}, answer:"D", explanation:"9/12 = 0.75 = 75% of boys play a sport." },
      { id:"u2q33", q:"If the conditional distributions of Y are identical across all categories of X, then X and Y are:", choices:{A:"perfectly correlated", B:"causally linked", C:"not associated (independent in the table)", D:"associated"}, answer:"C", explanation:"Identical conditional distributions mean knowing X tells you nothing about Y — no association." },
      { id:"u2q34", q:"The interior cells of a two-way table show:", choices:{A:"conditional percentages only", B:"the grand total", C:"marginal totals", D:"joint frequencies (counts for combinations of both variables)"}, answer:"D", explanation:"Interior cells give joint counts for each combination of the two variables' categories." },
      { id:"u2q35", q:"To compare whether two groups differ on a categorical response, you should compare their:", choices:{A:"conditional distributions", B:"marginal totals of the other variable", C:"grand totals", D:"correlation coefficients"}, answer:"A", explanation:"Comparing conditional distributions reveals whether the response differs by group." },
      { id:"u2q36", q:"If a scatterplot of y vs x is curved but log(y) vs x looks linear, a good model is:", choices:{A:"perfectly uncorrelated", B:"linear in x and y", C:"a power model only", D:"exponential (y grows by multiplicative factors)"}, answer:"D", explanation:"Linearity after a log transform of y indicates an exponential relationship between x and y." },
      { id:"u2q37", q:"Transforming data before fitting a line is done to:", choices:{A:"achieve approximate linearity so a linear model fits", B:"change categorical to quantitative", C:"increase the correlation to exactly 1", D:"remove all outliers"}, answer:"A", explanation:"Re-expressing variables (logs, powers, roots) can straighten a curved pattern so linear regression is appropriate." },
      { id:"u2q38", q:"A power model is suggested when which transformation linearizes the data?", choices:{A:"log(y) vs x", B:"y vs x²", C:"log(y) vs log(x)", D:"y vs log(x) only"}, answer:"C", explanation:"If log(y) vs log(x) is linear, a power model y = a·x^b fits the data." },
      { id:"u2q39", q:"After a successful transformation, you assess fit using:", choices:{A:"the original curved scatterplot", B:"the marginal distribution", C:"the residual plot of the transformed model", D:"the grand total"}, answer:"C", explanation:"You check the residual plot for the transformed (linear) model to confirm the fit improved." },
      { id:"u2q40", q:"A regression of weight on height gives slope 5 lb per inch. Best interpretation:", choices:{A:"The correlation is 5", B:"For each additional inch of height, predicted weight increases by 5 lb", C:"Taller people weigh 5 lb", D:"Weight causes height"}, answer:"B", explanation:"Slope is the predicted change in the response (weight) per one-unit increase in the explanatory variable (height)." },
      { id:"u2q41", q:"The intercept of a weight-on-height model is -200 lb. This is:", choices:{A:"an outlier", B:"not meaningful in context (height 0 is impossible)", C:"the slope", D:"a meaningful prediction at height 0"}, answer:"B", explanation:"Height 0 is outside any realistic range, so the intercept has no practical interpretation here — a common extrapolation caution." },
      { id:"u2q42", q:"Which of these can change dramatically due to a single influential point?", choices:{A:"the variable types", B:"the number of data values", C:"the axis labels", D:"the slope of the LSRL"}, answer:"D", explanation:"Influential points can swing the slope substantially." },
      { id:"u2q43", q:"Predicting y for an x within the observed data range is called:", choices:{A:"interpolation", B:"extrapolation", C:"a residual", D:"a lurking variable"}, answer:"A", explanation:"Interpolation is prediction within the range of observed x-values and is generally more reliable than extrapolation." },
      { id:"u2q44", q:"An observed value is 18 and the model predicts 15. The residual is:", choices:{A:"3", B:"0", C:"-3", D:"33"}, answer:"A", explanation:"Residual = observed - predicted = 18 - 15 = 3." },
      { id:"u2q45", q:"Which statement about correlation r is FALSE?", choices:{A:"It is unitless", B:"It lies between -1 and 1", C:"It is resistant to outliers", D:"It measures linear strength and direction"}, answer:"C", explanation:"Correlation is NOT resistant — outliers can strongly affect r. The other statements are true." },
      { id:"u2q46", q:"Model ŷ = 10 + 0.5x. For x = 20, observed y = 25. The residual is:", choices:{A:"-5", B:"5", C:"20", D:"0"}, answer:"B", explanation:"Predicted = 10 + 0.5(20) = 20; residual = 25 - 20 = 5." },
      { id:"u2q47", q:"Switching which variable is explanatory vs response changes:", choices:{A:"r²", B:"the value of r", C:"the slope of the regression line", D:"nothing about the data"}, answer:"C", explanation:"The LSRL slope depends on which variable is the response, so it changes; r and r² do not." },
      { id:"u2q48", q:"A correlation near 0 with an obvious U-shaped scatterplot tells you:", choices:{A:"the slope is steep", B:"there is a strong nonlinear relationship that r misses", C:"the variables are unrelated", D:"r was computed incorrectly"}, answer:"B", explanation:"r only captures linear association, so a strong curved (U-shaped) pattern can coexist with r ≈ 0." },
      { id:"u2q49", q:"High leverage points typically have:", choices:{A:"y-values equal to the mean", B:"no effect on the line", C:"x-values far from the mean of x", D:"residuals of exactly zero"}, answer:"C", explanation:"Leverage comes from extreme x-values, which give a point strong potential to influence the slope." },
      { id:"u2q50", q:"The best single numerical summary of how well a line fits, in terms of variation explained, is:", choices:{A:"r²", B:"the range", C:"the slope", D:"the intercept"}, answer:"A", explanation:"r² reports the fraction of response variation explained by the model — a direct measure of fit quality." },
    ]
  },
  {
    key: "apstat-u3", label: "U3: Collecting Data", icon: "🎲", color: "#7c3aed", bg: "#f5f3ff",
    questions: [
      { id:"u3q1", q:"A population is best described as:", choices:{A:"the group actually studied", B:"the entire group of individuals we want information about", C:"a subset chosen at random", D:"a numerical summary"}, answer:"B", explanation:"The population is the whole group of interest; a sample is the part of it we actually examine." },
      { id:"u3q2", q:"A sample is:", choices:{A:"the entire population", B:"a parameter", C:"a subset of the population from which we collect data", D:"always biased"}, answer:"C", explanation:"A sample is the portion of the population we actually gather data from." },
      { id:"u3q3", q:"A parameter is a number that describes the ____, while a statistic describes the ____.", choices:{A:"census; survey", B:"sample; population", C:"mean; median", D:"population; sample"}, answer:"D", explanation:"Parameters describe populations; statistics describe samples (mnemonic: p-p, s-s)." },
      { id:"u3q4", q:"The main advantage of random sampling is that it:", choices:{A:"is faster than other methods", B:"reduces bias by giving members known chances of selection", C:"guarantees a perfectly representative sample", D:"eliminates all sampling variability"}, answer:"B", explanation:"Random selection reduces bias; it does not remove sampling variability or guarantee perfect representativeness." },
      { id:"u3q5", q:"In a simple random sample (SRS) of size n,", choices:{A:"the sample is split into strata", B:"only the first n people are chosen", C:"every individual has the same chance, and every group of n is equally likely", D:"volunteers are used"}, answer:"C", explanation:"An SRS gives every possible group of size n an equal chance of being selected." },
      { id:"u3q6", q:"Dividing a population into groups of similar individuals and sampling from each group is:", choices:{A:"stratified random sampling", B:"systematic sampling", C:"cluster sampling", D:"convenience sampling"}, answer:"A", explanation:"Stratified sampling forms homogeneous strata and samples within each, improving precision when strata differ." },
      { id:"u3q7", q:"Splitting a population into groups, then randomly selecting whole groups to sample completely, is:", choices:{A:"voluntary response", B:"a census", C:"stratified sampling", D:"cluster sampling"}, answer:"D", explanation:"Cluster sampling selects entire clusters at random and includes all members of chosen clusters." },
      { id:"u3q8", q:"Selecting every 10th person on a list after a random start is:", choices:{A:"an SRS", B:"cluster sampling", C:"systematic sampling", D:"stratified sampling"}, answer:"C", explanation:"Systematic sampling chooses individuals at a fixed interval (e.g., every 10th) after a random starting point." },
      { id:"u3q9", q:"A magazine asks readers to mail in their opinions. This is an example of:", choices:{A:"voluntary response sampling, which tends to be biased", B:"stratified sampling", C:"an experiment", D:"a simple random sample"}, answer:"A", explanation:"Voluntary response samples over-represent people with strong opinions and are typically biased." },
      { id:"u3q10", q:"Interviewing the first 30 people you meet at a mall is:", choices:{A:"stratified sampling", B:"a census", C:"an SRS", D:"convenience sampling"}, answer:"D", explanation:"Choosing easy-to-reach individuals is convenience sampling, which is prone to bias." },
      { id:"u3q11", q:"Undercoverage occurs when:", choices:{A:"the experiment lacks a control group", B:"some groups of the population are left out of the sampling process", C:"respondents lie", D:"the sample is too large"}, answer:"B", explanation:"Undercoverage means part of the population has little or no chance of being sampled." },
      { id:"u3q12", q:"Nonresponse bias arises when:", choices:{A:"the question wording is leading", B:"selected individuals cannot be contacted or refuse to answer", C:"there is a placebo effect", D:"the sample is random"}, answer:"B", explanation:"Nonresponse bias occurs when chosen subjects do not respond and differ from those who do." },
      { id:"u3q13", q:"A poll question worded to push respondents toward an answer causes:", choices:{A:"undercoverage", B:"confounding", C:"response bias from question wording", D:"sampling variability"}, answer:"C", explanation:"Leading or loaded wording is a form of response bias." },
      { id:"u3q14", q:"Which sampling method is most likely to produce a biased sample?", choices:{A:"Stratified random sample", B:"Voluntary response sample", C:"Cluster random sample", D:"Simple random sample"}, answer:"B", explanation:"Voluntary response relies on self-selection and is the most prone to bias among the options." },
      { id:"u3q15", q:"The purpose of using a table of random digits or a random number generator is to:", choices:{A:"eliminate variability", B:"increase the sample size", C:"guarantee a normal distribution", D:"select individuals without bias"}, answer:"D", explanation:"Random selection tools help choose individuals fairly, reducing selection bias." },
      { id:"u3q16", q:"An observational study differs from an experiment because in an observational study, researchers:", choices:{A:"can prove causation", B:"impose a treatment on subjects", C:"always use random assignment", D:"do not impose a treatment; they only observe"}, answer:"D", explanation:"Observational studies record outcomes without assigning treatments, so they cannot establish causation." },
      { id:"u3q17", q:"Only a well-designed experiment can establish:", choices:{A:"a marginal distribution", B:"correlation", C:"a cause-and-effect relationship", D:"a sampling frame"}, answer:"C", explanation:"Random assignment in experiments allows cause-and-effect conclusions; observational studies cannot." },
      { id:"u3q18", q:"A confounding variable is one that:", choices:{A:"only appears in surveys", B:"is measured precisely", C:"is the same as the response", D:"is associated with both the explanatory variable and the response, blurring their relationship"}, answer:"D", explanation:"A confounder is linked to both the explanatory variable and the response, making their effects hard to separate." },
      { id:"u3q19", q:"The three principles of good experimental design are:", choices:{A:"control, randomization, and replication", B:"stratifying, clustering, and blocking", C:"random sampling, large n, and a census", D:"mean, median, and mode"}, answer:"A", explanation:"Good experiments use control of outside variables, randomization of treatments, and replication (enough subjects)." },
      { id:"u3q20", q:"Random assignment in an experiment serves to:", choices:{A:"create roughly equivalent treatment groups, balancing confounders", B:"increase the response rate", C:"select subjects from the population", D:"eliminate the need for a control group"}, answer:"A", explanation:"Randomly assigning treatments balances lurking variables across groups so differences can be attributed to the treatment." },
      { id:"u3q21", q:"A placebo is:", choices:{A:"a type of sampling", B:"a dummy treatment with no active ingredient", C:"a confounding variable", D:"an active dose of the real treatment"}, answer:"B", explanation:"A placebo is an inactive treatment used so the control group's experience mirrors the treatment group's." },
      { id:"u3q22", q:"The placebo effect refers to:", choices:{A:"a sampling error", B:"undercoverage", C:"the experimenter influencing the result", D:"subjects responding to a fake treatment because they believe it works"}, answer:"D", explanation:"Subjects may improve simply from believing they received treatment — the placebo effect." },
      { id:"u3q23", q:"A double-blind experiment means:", choices:{A:"only the subjects are unaware", B:"the sample is selected twice", C:"neither the subjects nor those measuring the response know who got which treatment", D:"the data are collected blindly at random"}, answer:"C", explanation:"In a double-blind design, both subjects and assessors are unaware of treatment assignments, reducing bias." },
      { id:"u3q24", q:"The control group in an experiment is used to:", choices:{A:"select the sample", B:"introduce confounding", C:"receive the largest dose", D:"provide a baseline for comparison"}, answer:"D", explanation:"The control group provides a comparison baseline against which treatment effects are judged." },
      { id:"u3q25", q:"Replication in an experiment means:", choices:{A:"using a placebo", B:"copying another study exactly", C:"using enough experimental units to reduce chance variation", D:"repeating the survey question"}, answer:"C", explanation:"Replication uses enough subjects (and can be repeated) so results are not due to chance alone." },
      { id:"u3q26", q:"Blocking in experimental design is most like ____ in sampling.", choices:{A:"clustering", B:"convenience sampling", C:"stratifying", D:"systematic sampling"}, answer:"C", explanation:"Blocking groups similar units before assigning treatments, analogous to stratifying before sampling." },
      { id:"u3q27", q:"You suspect age affects the response. Forming young and old blocks, then randomizing within each, controls for age. This is a:", choices:{A:"randomized block design", B:"completely randomized design", C:"cluster sample", D:"matched-pairs census"}, answer:"A", explanation:"Creating blocks by a variable (age) and randomizing within them is a randomized block design." },
      { id:"u3q28", q:"A matched-pairs design is a special case of blocking in which:", choices:{A:"each block has two similar units or each subject gets both treatments", B:"subjects choose their treatment", C:"there is no randomization", D:"only one treatment is used"}, answer:"A", explanation:"Matched pairs use blocks of two (or one subject under both treatments) to control variation." },
      { id:"u3q29", q:"An experiment's treatment is:", choices:{A:"the sample size", B:"a specific condition applied to subjects", C:"the response measured", D:"the population"}, answer:"B", explanation:"A treatment is a specific experimental condition imposed on the subjects." },
      { id:"u3q30", q:"Experimental units that are human beings are called:", choices:{A:"subjects", B:"factors", C:"clusters", D:"strata"}, answer:"A", explanation:"When experimental units are people, they are referred to as subjects." },
      { id:"u3q31", q:"A factor in an experiment is:", choices:{A:"a random digit", B:"a confounder", C:"an explanatory variable being manipulated", D:"the response variable"}, answer:"C", explanation:"A factor is an explanatory variable whose levels are set by the experimenter." },
      { id:"u3q32", q:"Two treatments are 'confounded' when:", choices:{A:"their effects cannot be distinguished from each other or another variable", B:"they use a placebo", C:"the sample is large", D:"they are randomly assigned"}, answer:"A", explanation:"Confounding means the effect of one variable cannot be separated from another's." },
      { id:"u3q33", q:"To generalize a study's results to a population, you need:", choices:{A:"random selection (sampling) from that population", B:"double-blinding", C:"random assignment of treatments", D:"a placebo group"}, answer:"A", explanation:"Random sampling supports generalization to the population; random assignment supports causal claims." },
      { id:"u3q34", q:"To conclude cause and effect, a study needs:", choices:{A:"a voluntary response sample", B:"a high response rate only", C:"a large convenience sample", D:"random assignment of treatments to groups"}, answer:"D", explanation:"Random assignment is what licenses cause-and-effect conclusions." },
      { id:"u3q35", q:"Which combination allows BOTH causal conclusions AND generalization to a population?", choices:{A:"Neither is needed", B:"Random assignment only", C:"Random sampling and random assignment", D:"Random sampling only"}, answer:"C", explanation:"Random sampling enables generalization; random assignment enables causation. Both together give you both." },
      { id:"u3q36", q:"A census is:", choices:{A:"an experiment", B:"a sample of half the population", C:"a stratified sample", D:"an attempt to collect data from every individual in the population"}, answer:"D", explanation:"A census gathers data from every member of the population." },
      { id:"u3q37", q:"Sampling variability refers to:", choices:{A:"undercoverage", B:"bias in the question wording", C:"confounding", D:"the natural variation in a statistic from sample to sample"}, answer:"D", explanation:"Different random samples give somewhat different statistics; that natural variation is sampling variability." },
      { id:"u3q38", q:"Increasing the sample size primarily:", choices:{A:"reduces bias", B:"guarantees a census", C:"reduces sampling variability", D:"creates confounding"}, answer:"C", explanation:"Larger samples reduce variability of estimates but do not fix bias in a flawed design." },
      { id:"u3q39", q:"A sampling frame is:", choices:{A:"the list of individuals from which the sample is actually drawn", B:"the response variable", C:"the treatment group", D:"a random number table"}, answer:"A", explanation:"The sampling frame is the list/source from which the sample is selected; gaps in it cause undercoverage." },
      { id:"u3q40", q:"Which is an example of response bias?", choices:{A:"Different samples give different means", B:"Selected people don't answer the phone", C:"Respondents underreport an embarrassing behavior", D:"Some neighborhoods are left off the call list"}, answer:"C", explanation:"Underreporting due to the sensitive nature of a question is response bias. Leaving neighborhoods off is undercoverage; not answering is nonresponse." },
      { id:"u3q41", q:"Assigning subjects to treatments by flipping a fair coin is a form of:", choices:{A:"stratifying", B:"confounding", C:"blocking", D:"randomization"}, answer:"D", explanation:"Using a coin (or random digits) to assign treatments is randomization." },
      { id:"u3q42", q:"An experiment with one factor at three dose levels has how many treatments (if no other factor)?", choices:{A:"6", B:"1", C:"2", D:"3"}, answer:"D", explanation:"With a single factor, the number of treatments equals the number of levels — here, 3." },
      { id:"u3q43", q:"A study compares 2 factors, one with 2 levels and one with 3 levels. How many treatments?", choices:{A:"5", B:"3", C:"6", D:"2"}, answer:"C", explanation:"Treatments = product of levels = 2 × 3 = 6." },
      { id:"u3q44", q:"Lack of realism (the experimental setting differs from real life) threatens a study's:", choices:{A:"randomization", B:"control group", C:"blinding", D:"ability to generalize conclusions"}, answer:"D", explanation:"If the setting is unrealistic, results may not generalize to real-world conditions." },
      { id:"u3q45", q:"A completely randomized design assigns:", choices:{A:"subjects to blocks first", B:"all treatments to every subject", C:"treatments to all experimental units entirely by chance", D:"only the control group at random"}, answer:"C", explanation:"In a completely randomized design, every unit is assigned to a treatment purely at random, with no blocking." },
      { id:"u3q46", q:"Which best reduces the effect of a known confounding variable like sex?", choices:{A:"Use a placebo", B:"Ignore it", C:"Block on sex, then randomize within blocks", D:"Use a larger voluntary response sample"}, answer:"C", explanation:"Blocking on the confounder isolates its effect, and randomizing within blocks handles other variables." },
      { id:"u3q47", q:"A researcher records diet and health for people who chose their own diets. This is:", choices:{A:"an experiment with random assignment", B:"a matched-pairs experiment", C:"an observational study, so causation can't be concluded", D:"a census"}, answer:"C", explanation:"Because subjects self-selected diets (no imposed treatment), it's observational and cannot establish causation." },
      { id:"u3q48", q:"The 'experimental units' are:", choices:{A:"the individuals or objects to which treatments are applied", B:"the response values", C:"the population list", D:"the random digits used"}, answer:"A", explanation:"Experimental units are the things (people, plots, animals) that receive the treatments." },
      { id:"u3q49", q:"Wording two survey versions differently to study question effects addresses:", choices:{A:"response bias from wording", B:"sampling variability", C:"replication", D:"undercoverage"}, answer:"A", explanation:"Comparing wordings investigates response bias caused by how questions are phrased." },
      { id:"u3q50", q:"Which statement is TRUE?", choices:{A:"Random sampling lets us infer causation", B:"A large sample removes bias", C:"Observational studies prove cause and effect", D:"Random assignment lets us infer causation"}, answer:"D", explanation:"Only random assignment supports causal inference; sampling supports generalization; large n doesn't fix bias." },
    ]
  },
  {
    key: "apstat-u4", label: "U4: Probability & Random Variables", icon: "🃏", color: "#dc2626", bg: "#fef2f2",
    questions: [
      { id:"u4q1", q:"A probability must always be:", choices:{A:"exactly 0.5", B:"greater than 1", C:"a negative number", D:"between 0 and 1 inclusive"}, answer:"D", explanation:"Any probability P satisfies 0 ≤ P ≤ 1." },
      { id:"u4q2", q:"The probabilities of all outcomes in a sample space must sum to:", choices:{A:"1", B:"100", C:"0.5", D:"0"}, answer:"A", explanation:"A valid probability distribution's outcomes sum to 1." },
      { id:"u4q3", q:"A fair six-sided die is rolled. P(rolling a 4) is:", choices:{A:"4/6", B:"1/6", C:"1/4", D:"1/3"}, answer:"B", explanation:"One favorable outcome out of six equally likely outcomes: 1/6." },
      { id:"u4q4", q:"The complement rule states P(not A) equals:", choices:{A:"1 - P(A)", B:"1 + P(A)", C:"P(A)²", D:"P(A) - 1"}, answer:"A", explanation:"P(A^c) = 1 - P(A)." },
      { id:"u4q5", q:"If P(A) = 0.3, then P(not A) is:", choices:{A:"0.7", B:"0.09", C:"0.3", D:"1.3"}, answer:"A", explanation:"1 - 0.3 = 0.7." },
      { id:"u4q6", q:"Two events are mutually exclusive (disjoint) if:", choices:{A:"they have no outcomes in common", B:"they are independent", C:"they always occur together", D:"P(A and B) = P(A)P(B)"}, answer:"A", explanation:"Mutually exclusive events cannot both happen, so P(A and B) = 0." },
      { id:"u4q7", q:"For mutually exclusive events A and B, P(A or B) equals:", choices:{A:"1", B:"P(A) - P(B)", C:"P(A) + P(B)", D:"P(A)P(B)"}, answer:"C", explanation:"With no overlap, the addition rule simplifies to P(A) + P(B)." },
      { id:"u4q8", q:"P(A) = 0.5, P(B) = 0.4, P(A and B) = 0.2. Then P(A or B) is:", choices:{A:"0.2", B:"0.7", C:"1.1", D:"0.9"}, answer:"B", explanation:"General addition rule: 0.5 + 0.4 - 0.2 = 0.7." },
      { id:"u4q9", q:"Two events are independent if:", choices:{A:"they are disjoint", B:"P(A or B) = 1", C:"P(A) = P(B)", D:"P(A and B) = P(A)·P(B)"}, answer:"D", explanation:"Independence means one event's occurrence doesn't change the other's probability: P(A and B) = P(A)P(B)." },
      { id:"u4q10", q:"Two independent events each have probability 0.5. P(both occur) is:", choices:{A:"1.0", B:"0.0", C:"0.25", D:"0.5"}, answer:"C", explanation:"For independent events, multiply: 0.5 × 0.5 = 0.25." },
      { id:"u4q11", q:"Conditional probability P(B | A) is defined as:", choices:{A:"P(A and B) · P(A)", B:"P(A) / P(B)", C:"P(A and B) / P(A)", D:"P(A) + P(B)"}, answer:"C", explanation:"P(B | A) = P(A and B) / P(A), the probability of B given that A occurred." },
      { id:"u4q12", q:"If P(A and B) = 0.12 and P(A) = 0.3, then P(B | A) is:", choices:{A:"0.12", B:"0.36", C:"0.42", D:"0.40"}, answer:"D", explanation:"P(B|A) = 0.12 / 0.30 = 0.40." },
      { id:"u4q13", q:"If A and B are independent, then P(B | A) equals:", choices:{A:"0", B:"1", C:"P(B)", D:"P(A)"}, answer:"C", explanation:"Independence means conditioning on A doesn't change B: P(B|A) = P(B)." },
      { id:"u4q14", q:"Mutually exclusive events with positive probability are:", choices:{A:"always independent", B:"never independent", C:"sometimes independent", D:"always equally likely"}, answer:"B", explanation:"If disjoint events both have positive probability, knowing one occurred makes the other impossible, so they cannot be independent." },
      { id:"u4q15", q:"A random variable is:", choices:{A:"the sample size", B:"a variable whose value is a numerical outcome of a random process", C:"always categorical", D:"a fixed constant"}, answer:"B", explanation:"A random variable assigns a number to each outcome of a random phenomenon." },
      { id:"u4q16", q:"A discrete random variable:", choices:{A:"can take any value in an interval", B:"is always continuous", C:"has no probability distribution", D:"takes a countable set of values"}, answer:"D", explanation:"Discrete random variables take separate, countable values (e.g., 0,1,2,...)." },
      { id:"u4q17", q:"The expected value (mean) of a discrete random variable is found by:", choices:{A:"adding all the x-values", B:"averaging the probabilities", C:"taking the largest value", D:"summing each value times its probability, Σx·P(x)"}, answer:"D", explanation:"E(X) = Σ x·P(x), a probability-weighted average of the values." },
      { id:"u4q18", q:"X takes values 0,1,2 with probabilities 0.2, 0.5, 0.3. E(X) equals:", choices:{A:"0.9", B:"1.1", C:"1.0", D:"1.5"}, answer:"B", explanation:"E(X) = 0(0.2)+1(0.5)+2(0.3) = 1.1." },
      { id:"u4q19", q:"A game pays $5 with probability 0.3 and loses $2 with probability 0.7. The expected value is:", choices:{A:"-$0.50", B:"$0.10", C:"$3.00", D:"$1.50"}, answer:"B", explanation:"E = 5(0.3) + (-2)(0.7) = 1.5 - 1.4 = $0.10." },
      { id:"u4q20", q:"For independent random variables X and Y, the variance of X + Y equals:", choices:{A:"SD(X) + SD(Y)", B:"Var(X)·Var(Y)", C:"Var(X) - Var(Y)", D:"Var(X) + Var(Y)"}, answer:"D", explanation:"Variances add for independent variables (even for X - Y), though standard deviations do not add directly." },
      { id:"u4q21", q:"For ANY random variables X and Y, the mean of X + Y equals:", choices:{A:"E(X) + E(Y)", B:"E(X) - E(Y)", C:"E(X)·E(Y)", D:"requires independence to compute"}, answer:"A", explanation:"Means always add: E(X+Y) = E(X) + E(Y), independent or not." },
      { id:"u4q22", q:"If E(X) = 10 and Y = 3X + 2, then E(Y) equals:", choices:{A:"30", B:"23", C:"32", D:"12"}, answer:"C", explanation:"E(3X+2) = 3·E(X) + 2 = 3(10)+2 = 32." },
      { id:"u4q23", q:"If SD(X) = 4 and Y = 3X + 2, then SD(Y) equals:", choices:{A:"4", B:"12", C:"6", D:"14"}, answer:"B", explanation:"Adding a constant doesn't change spread; multiplying by 3 multiplies SD by 3: SD(Y)=3·4=12." },
      { id:"u4q24", q:"For independent X and Y with Var(X)=9 and Var(Y)=16, SD(X+Y) equals:", choices:{A:"5", B:"25", C:"12.5", D:"7"}, answer:"A", explanation:"Var(X+Y)=9+16=25, so SD = √25 = 5." },
      { id:"u4q25", q:"For independent X and Y with Var(X)=9 and Var(Y)=16, SD(X - Y) equals:", choices:{A:"5", B:"-5", C:"1", D:"7"}, answer:"A", explanation:"Variances still ADD for a difference: 9+16=25, SD=√25=5." },
      { id:"u4q26", q:"Which is NOT a condition for a binomial setting?", choices:{A:"A fixed number of trials n", B:"The number of successes is fixed in advance", C:"Each trial has two outcomes (success/failure)", D:"Each trial is independent"}, answer:"B", explanation:"Binomial requires fixed n, two outcomes, constant success probability p, and independence — but the number of successes is the random variable, not fixed." },
      { id:"u4q27", q:"In a binomial setting, the probability of exactly k successes uses the formula:", choices:{A:"k/n", B:"n · p", C:"p^n", D:"nCk · p^k · (1-p)^(n-k)"}, answer:"D", explanation:"P(X=k) = C(n,k)·p^k·(1-p)^(n-k)." },
      { id:"u4q28", q:"A binomial variable has n = 20, p = 0.3. Its mean (expected successes) is:", choices:{A:"14", B:"6", C:"0.3", D:"3"}, answer:"B", explanation:"Mean of a binomial = n·p = 20(0.3) = 6." },
      { id:"u4q29", q:"A binomial variable has n = 100, p = 0.5. Its standard deviation is:", choices:{A:"10", B:"25", C:"50", D:"5"}, answer:"D", explanation:"SD = √(np(1-p)) = √(100·0.5·0.5) = √25 = 5." },
      { id:"u4q30", q:"A fair coin is flipped 5 times. P(all 5 are heads) is:", choices:{A:"1/5", B:"1/16", C:"5/32", D:"1/32"}, answer:"D", explanation:"P = (1/2)^5 = 1/32." },
      { id:"u4q31", q:"A fair coin is flipped 4 times. P(exactly 2 heads) is:", choices:{A:"3/8", B:"1/2", C:"1/16", D:"1/4"}, answer:"A", explanation:"P = C(4,2)(0.5)^2(0.5)^2 = 6/16 = 3/8." },
      { id:"u4q32", q:"The binomial coefficient C(n, k) counts:", choices:{A:"the mean", B:"the probability of success", C:"the variance", D:"the number of ways to choose k successes among n trials"}, answer:"D", explanation:"C(n,k) = n!/(k!(n-k)!) counts the arrangements of k successes in n trials." },
      { id:"u4q33", q:"A geometric random variable counts:", choices:{A:"the number of successes in n trials", B:"the number of trials until the first success", C:"the number of categories", D:"the mean of the data"}, answer:"B", explanation:"Geometric variables count trials up to and including the first success." },
      { id:"u4q34", q:"For a geometric distribution with p = 0.25, the expected number of trials until the first success is:", choices:{A:"0.25", B:"8", C:"2", D:"4"}, answer:"D", explanation:"Mean of geometric = 1/p = 1/0.25 = 4." },
      { id:"u4q35", q:"P(first success on the 3rd trial) when p = 0.2 is:", choices:{A:"(0.8)(0.2)²", B:"(0.8)²(0.2)", C:"(0.2)³", D:"3(0.2)"}, answer:"B", explanation:"Geometric: two failures then a success = (0.8)²(0.2)." },
      { id:"u4q36", q:"In a standard normal distribution, the mean and standard deviation are:", choices:{A:"mean 0.5, SD 0.5", B:"mean 0, SD 1", C:"mean 1, SD 0", D:"mean 100, SD 15"}, answer:"B", explanation:"The standard normal N(0,1) has mean 0 and standard deviation 1." },
      { id:"u4q37", q:"About what percent of a normal distribution lies within 2 standard deviations of the mean?", choices:{A:"50%", B:"95%", C:"68%", D:"99.7%"}, answer:"B", explanation:"By the empirical rule, ~95% lies within 2 SD." },
      { id:"u4q38", q:"To find the proportion of a normal distribution below a value, you:", choices:{A:"multiply by n", B:"square the value", C:"use the binomial formula", D:"compute the z-score and find the area to its left"}, answer:"D", explanation:"Standardize to a z-score, then use the normal table/calculator for the left-tail area." },
      { id:"u4q39", q:"IQ scores are N(100, 15). The z-score for an IQ of 130 is:", choices:{A:"0.5", B:"1", C:"3", D:"2"}, answer:"D", explanation:"z = (130-100)/15 = 2." },
      { id:"u4q40", q:"A z-score of 1.5 corresponds to a value that is:", choices:{A:"below the mean", B:"at the 15th percentile", C:"1.5 standard deviations above the mean", D:"1.5 units above the mean"}, answer:"C", explanation:"z measures distance in standard deviations; z=1.5 is 1.5 SD above the mean." },
      { id:"u4q41", q:"P(A or B) = P(A) + P(B) - P(A and B) is called the:", choices:{A:"complement rule", B:"general addition rule", C:"multiplication rule", D:"law of large numbers"}, answer:"B", explanation:"This is the general addition rule for the union of two events." },
      { id:"u4q42", q:"The Law of Large Numbers says that as the number of trials increases:", choices:{A:"each outcome becomes equally likely", B:"the sample proportion approaches the true probability", C:"variance increases without bound", D:"the mean becomes 0"}, answer:"B", explanation:"Observed relative frequency converges to the true probability as trials increase." },
      { id:"u4q43", q:"Simulation is used in probability to:", choices:{A:"replace random assignment", B:"estimate probabilities by imitating a random process many times", C:"remove variability", D:"compute exact probabilities algebraically"}, answer:"B", explanation:"Simulation imitates a chance process repeatedly to estimate probabilities empirically." },
      { id:"u4q44", q:"Of 200 people, 80 own a dog and of those 30 also own a cat. P(cat | dog) is:", choices:{A:"0.15", B:"0.375", C:"0.40", D:"0.30"}, answer:"B", explanation:"P(cat|dog) = 30/80 = 0.375." },
      { id:"u4q45", q:"P(A) = 0.6 and P(B | A) = 0.5. Then P(A and B) equals:", choices:{A:"1.1", B:"0.5", C:"0.3", D:"0.6"}, answer:"C", explanation:"Multiplication rule: P(A and B) = P(A)·P(B|A) = 0.6 × 0.5 = 0.3." },
      { id:"u4q46", q:"Adding two independent normal random variables produces a distribution that is:", choices:{A:"binomial", B:"normal", C:"skewed right", D:"uniform"}, answer:"B", explanation:"Any linear combination (including a sum) of independent normal variables is itself normal." },
      { id:"u4q47", q:"If X and Y are NOT independent, which still holds?", choices:{A:"E(X+Y) = E(X) + E(Y)", B:"SD(X+Y) = SD(X) + SD(Y)", C:"P(X and Y)=P(X)P(Y)", D:"Var(X+Y) = Var(X) + Var(Y)"}, answer:"A", explanation:"Means always add regardless of independence; the variance rule requires independence." },
      { id:"u4q48", q:"A game is 'fair' when its expected value (net gain) is:", choices:{A:"positive", B:"greater than 1", C:"zero", D:"negative"}, answer:"C", explanation:"A fair game has expected net gain of 0 — neither player is favored on average." },
      { id:"u4q49", q:"A fair coin is flipped 3 times. P(at least one head) is:", choices:{A:"7/8", B:"3/8", C:"1/2", D:"1/8"}, answer:"A", explanation:"P(at least one) = 1 - P(no heads) = 1 - (1/2)³ = 1 - 1/8 = 7/8." },
      { id:"u4q50", q:"A probability distribution table is valid only if every probability is between 0 and 1 AND:", choices:{A:"the probabilities sum to 1", B:"there are exactly 4 outcomes", C:"all probabilities are equal", D:"the mean is 0"}, answer:"A", explanation:"A valid distribution needs each 0≤P≤1 and a total of 1." },
    ]
  },
  {
    key: "apstat-u5", label: "U5: Sampling Distributions", icon: "📐", color: "#ea580c", bg: "#fff7ed",
    questions: [
      { id:"u5q1", q:"A sampling distribution is the distribution of:", choices:{A:"a statistic over all possible samples of a given size", B:"the population values", C:"the residuals", D:"the individuals in one sample"}, answer:"A", explanation:"A sampling distribution describes how a statistic (like x̄ or p̂) varies across all possible samples of size n." },
      { id:"u5q2", q:"A statistic is an unbiased estimator of a parameter when:", choices:{A:"its variance is zero", B:"the sample is large", C:"its sampling distribution is centered at the parameter", D:"it always equals the parameter"}, answer:"C", explanation:"Unbiased means the mean of the statistic's sampling distribution equals the true parameter." },
      { id:"u5q3", q:"Bias refers to:", choices:{A:"a systematic tendency to over- or under-estimate the parameter", B:"how spread out a statistic is", C:"the sample size", D:"random sampling error only"}, answer:"A", explanation:"Bias is a consistent (systematic) error in one direction, separate from variability." },
      { id:"u5q4", q:"The variability of a statistic is reduced primarily by:", choices:{A:"using a biased method", B:"taking fewer samples", C:"increasing the sample size", D:"increasing the population size"}, answer:"C", explanation:"Larger samples produce sampling distributions with less spread (smaller standard error)." },
      { id:"u5q5", q:"An estimator with low bias and low variability is described as:", choices:{A:"neither", B:"both accurate (centered) and precise (low spread)", C:"precise but inaccurate", D:"accurate but not precise"}, answer:"B", explanation:"Low bias = accurate/centered on the parameter; low variability = precise." },
      { id:"u5q6", q:"The mean of the sampling distribution of p̂ equals:", choices:{A:"0", B:"p̂", C:"n·p", D:"p, the population proportion"}, answer:"D", explanation:"p̂ is unbiased: the mean of its sampling distribution is the true proportion p." },
      { id:"u5q7", q:"For p = 0.4 and n = 100, the standard deviation of p̂ is:", choices:{A:"0.24", B:"0.04", C:"0.049", D:"0.16"}, answer:"C", explanation:"SD(p̂) = √(p(1-p)/n) = √(0.4·0.6/100) = √0.0024 ≈ 0.049." },
      { id:"u5q8", q:"The formula for the standard deviation of p̂ is:", choices:{A:"p(1-p)/n", B:"√(p(1-p)/n)", C:"σ/√n", D:"√(np(1-p))"}, answer:"B", explanation:"SD(p̂) = √(p(1-p)/n)." },
      { id:"u5q9", q:"The 10% condition for sampling distributions requires that:", choices:{A:"the sample is at least 10% of the population", B:"the sample is no more than 10% of the population", C:"n ≥ 10", D:"p̂ is at least 0.10"}, answer:"B", explanation:"Sampling without replacement keeps observations roughly independent when n ≤ 10% of the population." },
      { id:"u5q10", q:"The Large Counts condition for p̂ to be approximately normal requires:", choices:{A:"the population is normal", B:"n ≥ 30", C:"p ≥ 0.5", D:"np ≥ 10 and n(1-p) ≥ 10"}, answer:"D", explanation:"Large Counts: both np and n(1-p) at least 10 makes the sampling distribution of p̂ approximately normal." },
      { id:"u5q11", q:"As sample size n increases, the standard deviation of p̂:", choices:{A:"stays the same", B:"decreases", C:"increases", D:"becomes negative"}, answer:"B", explanation:"Because n is in the denominator under the root, larger n gives smaller SD(p̂)." },
      { id:"u5q12", q:"If np ≥ 10 and n(1-p) ≥ 10, the sampling distribution of p̂ is approximately:", choices:{A:"normal", B:"uniform", C:"binomial only", D:"skewed right"}, answer:"A", explanation:"Meeting Large Counts makes the distribution of p̂ approximately normal." },
      { id:"u5q13", q:"The mean of the sampling distribution of x̄ equals:", choices:{A:"μ, the population mean", B:"0", C:"x̄", D:"σ"}, answer:"A", explanation:"x̄ is unbiased: the center of its sampling distribution is the population mean μ." },
      { id:"u5q14", q:"A population has σ = 20. For samples of size n = 25, the standard deviation of x̄ is:", choices:{A:"0.8", B:"5", C:"4", D:"20"}, answer:"C", explanation:"SD(x̄) = σ/√n = 20/√25 = 20/5 = 4." },
      { id:"u5q15", q:"The standard deviation of the sample mean x̄ is given by:", choices:{A:"σ/√n", B:"σ/n", C:"√(p(1-p)/n)", D:"σ·√n"}, answer:"A", explanation:"SD(x̄) = σ/√n, the population SD divided by the square root of n." },
      { id:"u5q16", q:"The Central Limit Theorem (CLT) states that for large n, the sampling distribution of x̄ is:", choices:{A:"uniform", B:"skewed like the population", C:"always identical to the population", D:"approximately normal regardless of population shape"}, answer:"D", explanation:"The CLT says x̄ becomes approximately normal as n grows, even if the population is not normal." },
      { id:"u5q17", q:"A common rule of thumb for the CLT to apply to x̄ is:", choices:{A:"n ≥ 30", B:"n ≥ 10", C:"n ≤ 5", D:"np ≥ 10"}, answer:"A", explanation:"n ≥ 30 is the usual guideline for x̄ to be approximately normal when the population isn't normal." },
      { id:"u5q18", q:"If the population is already normal, the sampling distribution of x̄ is:", choices:{A:"normal only if n ≥ 30", B:"normal for any sample size n", C:"never normal", D:"uniform"}, answer:"B", explanation:"When the population is normal, x̄ is exactly normal for every sample size." },
      { id:"u5q19", q:"Doubling the sample size changes SD(x̄) by a factor of:", choices:{A:"1/√2", B:"√2", C:"1/2", D:"2"}, answer:"A", explanation:"SD(x̄)=σ/√n, so multiplying n by 2 multiplies √n by √2, dividing the SD by √2." },
      { id:"u5q20", q:"To cut the standard deviation of x̄ in half, the sample size must be:", choices:{A:"squared", B:"quadrupled", C:"halved", D:"doubled"}, answer:"B", explanation:"Since SD ∝ 1/√n, you need 4× the sample size to halve the SD." },
      { id:"u5q21", q:"'Standard error' refers to:", choices:{A:"the standard deviation of a sampling distribution (often estimated from data)", B:"a mistake in the data", C:"the bias of an estimator", D:"the population standard deviation"}, answer:"A", explanation:"Standard error is the (estimated) standard deviation of a statistic's sampling distribution." },
      { id:"u5q22", q:"Population μ = 50, σ = 10. For n = 4, what is the z-score for x̄ = 53?", choices:{A:"0.60", B:"0.30", C:"1.2", D:"3.0"}, answer:"A", explanation:"SD(x̄)=10/√4=5; z=(53-50)/5=0.60." },
      { id:"u5q23", q:"Which has a smaller standard deviation: the distribution of individuals or the distribution of x̄ (same population)?", choices:{A:"they are equal", B:"cannot be compared", C:"the sampling distribution of x̄", D:"individuals"}, answer:"C", explanation:"Averaging reduces variability, so SD(x̄)=σ/√n is smaller than σ for n>1." },
      { id:"u5q24", q:"The mean of the sampling distribution of p̂₁ - p̂₂ is:", choices:{A:"p₁ - p₂", B:"p̂₁ - p̂₂", C:"p₁ + p₂", D:"0 always"}, answer:"A", explanation:"The difference of sample proportions is unbiased for p₁ - p₂." },
      { id:"u5q25", q:"For independent samples, the variance of x̄₁ - x̄₂ equals:", choices:{A:"0", B:"Var(x̄₁) - Var(x̄₂)", C:"Var(x̄₁) + Var(x̄₂)", D:"Var(x̄₁)·Var(x̄₂)"}, answer:"C", explanation:"Variances add for independent statistics, even for a difference." },
      { id:"u5q26", q:"Sampling variability is:", choices:{A:"the fact that statistics differ from sample to sample", B:"a measurement error", C:"bias in the design", D:"the population mean"}, answer:"A", explanation:"Different random samples yield different statistic values; that natural variation is sampling variability." },
      { id:"u5q27", q:"Which statement is true about unbiased estimators?", choices:{A:"They have zero variability", B:"They always equal the parameter in every sample", C:"On average across samples they equal the parameter", D:"They require n ≥ 30"}, answer:"C", explanation:"Unbiasedness is an 'on average' property of the sampling distribution's center, not a guarantee per sample." },
      { id:"u5q28", q:"If a sampling method is biased, increasing the sample size will:", choices:{A:"make the estimator unbiased", B:"remove the bias", C:"increase variability", D:"not remove the bias"}, answer:"D", explanation:"Bias is a design flaw; bigger samples reduce variability but do not fix bias." },
      { id:"u5q29", q:"The shape of the sampling distribution of p̂ when np and n(1-p) are both large is:", choices:{A:"uniform", B:"approximately normal", C:"bimodal", D:"strongly skewed"}, answer:"B", explanation:"Large Counts conditions yield an approximately normal sampling distribution for p̂." },
      { id:"u5q30", q:"For a sample proportion, the center of its sampling distribution does NOT depend on:", choices:{A:"the population size only", B:"the sample size n", C:"neither; center is always p", D:"the true proportion p"}, answer:"B", explanation:"The center of p̂'s distribution is p regardless of n; n affects only the spread." },
      { id:"u5q31", q:"For p = 0.5 and n = 400, SD(p̂) equals:", choices:{A:"0.025", B:"0.25", C:"0.05", D:"0.0025"}, answer:"A", explanation:"√(0.5·0.5/400)=√(0.25/400)=√0.000625=0.025." },
      { id:"u5q32", q:"A larger population (with sample size fixed) changes the standard deviation of x̄:", choices:{A:"doubles it", B:"a lot", C:"to zero", D:"essentially not at all"}, answer:"D", explanation:"SD(x̄)=σ/√n depends on n, not population size (given the 10% condition); population size barely matters." },
      { id:"u5q33", q:"Which sampling distribution is exactly normal even for small n?", choices:{A:"p̂ for any p", B:"none", C:"x̄ from a normal population", D:"x̄ from a skewed population"}, answer:"C", explanation:"If the population is normal, x̄ is exactly normal for all n." },
      { id:"u5q34", q:"The standard error of x̄ is computed from data as:", choices:{A:"σ/n", B:"s/√n", C:"s·√n", D:"√(p̂(1-p̂)/n)"}, answer:"B", explanation:"When σ is unknown, the standard error of x̄ uses the sample SD: s/√n." },
      { id:"u5q35", q:"Increasing n makes the sampling distribution of a statistic:", choices:{A:"narrower (less spread)", B:"wider", C:"shift its center", D:"more skewed"}, answer:"A", explanation:"Larger samples reduce the spread of the sampling distribution; the center stays put." },
      { id:"u5q36", q:"Which is a parameter, not a statistic?", choices:{A:"μ", B:"s", C:"x̄", D:"p̂"}, answer:"A", explanation:"μ is a population parameter; x̄, p̂, and s are computed from samples." },
      { id:"u5q37", q:"The sampling distribution model lets us:", choices:{A:"prove causation", B:"remove sampling variability", C:"describe the likely values of a statistic and quantify uncertainty", D:"eliminate bias"}, answer:"C", explanation:"Knowing a statistic's sampling distribution lets us judge typical values and build inference." },
      { id:"u5q38", q:"When p is close to 0 or 1 and n is small, the sampling distribution of p̂ is:", choices:{A:"approximately normal", B:"exactly normal", C:"uniform", D:"skewed"}, answer:"D", explanation:"Without Large Counts, p̂ near the boundaries is skewed rather than normal." },
      { id:"u5q39", q:"Two unbiased estimators differ in variability. The better one has:", choices:{A:"smaller variability", B:"larger variability", C:"more bias", D:"a larger sample requirement"}, answer:"A", explanation:"Among unbiased estimators, the one with smaller variability is preferred (more precise)." },
      { id:"u5q40", q:"A simulation of a sampling distribution is built by:", choices:{A:"using the whole population once", B:"computing a single mean", C:"taking many samples and recording the statistic each time", D:"taking one large sample"}, answer:"C", explanation:"Repeatedly sampling and recording the statistic approximates its sampling distribution." },
      { id:"u5q41", q:"Population σ = 15, n = 9. The standard deviation of x̄ is:", choices:{A:"5", B:"1.67", C:"45", D:"15"}, answer:"A", explanation:"σ/√n = 15/√9 = 15/3 = 5." },
      { id:"u5q42", q:"If you quadruple the sample size, the standard error is:", choices:{A:"doubled", B:"quartered", C:"unchanged", D:"halved"}, answer:"D", explanation:"SE ∝ 1/√n; 4× the n means √n doubles, so SE is halved." },
      { id:"u5q43", q:"An estimator's accuracy is described by its ____ and its precision by its ____.", choices:{A:"bias; variability", B:"mean; mode", C:"variability; bias", D:"sample; population"}, answer:"A", explanation:"Accuracy relates to bias (centering); precision relates to variability (spread)." },
      { id:"u5q44", q:"For p̂ to be used in a normal approximation, you check:", choices:{A:"p = 0.5", B:"the population is normal", C:"only n ≥ 30", D:"Random, 10%, and Large Counts conditions"}, answer:"D", explanation:"Inference for proportions checks Random sampling, the 10% condition, and Large Counts." },
      { id:"u5q45", q:"The sampling distribution of x̄ from a heavily skewed population with n = 5 is:", choices:{A:"approximately normal", B:"uniform", C:"still noticeably skewed", D:"exactly normal"}, answer:"C", explanation:"With small n and a skewed population, x̄ remains skewed; the CLT needs larger n." },
      { id:"u5q46", q:"Which quantity gets smaller as sample size grows, holding all else fixed?", choices:{A:"the parameter", B:"the bias", C:"the standard error", D:"the population mean"}, answer:"C", explanation:"Standard error decreases with larger n; bias and the parameter do not depend on n." },
      { id:"u5q47", q:"The center of the sampling distribution of an unbiased statistic equals:", choices:{A:"zero", B:"the standard error", C:"the parameter being estimated", D:"the sample size"}, answer:"C", explanation:"Unbiased statistics are centered exactly at the parameter." },
      { id:"u5q48", q:"Compared to SD(p̂) at n = 100, SD(p̂) at n = 400 (same p) is:", choices:{A:"half as large", B:"twice as large", C:"the same", D:"four times as large"}, answer:"A", explanation:"n goes ×4, √n goes ×2, so SD(p̂) is halved." },
      { id:"u5q49", q:"The key idea that makes inference possible is that statistics have:", choices:{A:"the same value as parameters", B:"predictable sampling distributions", C:"fixed values", D:"no variability"}, answer:"B", explanation:"Because statistics vary in predictable (modelable) ways, we can quantify uncertainty and do inference." },
      { id:"u5q50", q:"Which condition ensures observations are approximately independent when sampling without replacement?", choices:{A:"Large Counts", B:"normal population", C:"n ≥ 30", D:"the 10% condition"}, answer:"D", explanation:"The 10% condition (n ≤ 0.10·N) keeps without-replacement sampling close to independent." },
    ]
  },
  {
    key: "apstat-u6", label: "U6: Inference for Proportions", icon: "📊", color: "#2563eb", bg: "#eff6ff",
    questions: [
      { id:"u6q1", q:"A confidence interval gives:", choices:{A:"a single best estimate", B:"a range of plausible values for a parameter", C:"the sample size needed", D:"the exact parameter value"}, answer:"B", explanation:"A confidence interval is an interval of plausible parameter values produced by a method with a known success rate." },
      { id:"u6q2", q:"The general form of a confidence interval is:", choices:{A:"statistic ± (critical value)(standard error)", B:"parameter ± margin", C:"statistic × standard error", D:"mean ÷ √n"}, answer:"A", explanation:"CI = point estimate ± (critical value)·(standard error)." },
      { id:"u6q3", q:"The correct interpretation of '95% confidence' is:", choices:{A:"95% of samples equal the parameter", B:"the method captures the true parameter in 95% of all such samples", C:"there is a 95% chance the parameter is a specific number", D:"95% of the data lie in the interval"}, answer:"B", explanation:"Confidence refers to the long-run capture rate of the method, not a probability about one fixed interval." },
      { id:"u6q4", q:"The standard error of p̂ in a one-sample z-interval is:", choices:{A:"√(p(1-p)/n)", B:"√(p̂(1-p̂)/n)", C:"p̂/n", D:"σ/√n"}, answer:"B", explanation:"For a CI, the SE uses p̂ since p is unknown: √(p̂(1-p̂)/n)." },
      { id:"u6q5", q:"The margin of error in a confidence interval increases when:", choices:{A:"the sample size increases", B:"variability decreases", C:"the confidence level increases", D:"the standard error decreases"}, answer:"C", explanation:"Higher confidence uses a larger critical value, widening the margin of error." },
      { id:"u6q6", q:"To halve the margin of error (all else equal), multiply the sample size by:", choices:{A:"1/2", B:"2", C:"√2", D:"4"}, answer:"D", explanation:"Margin of error ∝ 1/√n, so 4× the sample size halves it." },
      { id:"u6q7", q:"The critical value z* for a 95% confidence interval is approximately:", choices:{A:"1.28", B:"1.645", C:"2.576", D:"1.96"}, answer:"D", explanation:"z* ≈ 1.96 for 95% confidence." },
      { id:"u6q8", q:"The critical value z* for a 90% confidence interval is approximately:", choices:{A:"1.645", B:"1.96", C:"1.0", D:"2.576"}, answer:"A", explanation:"z* ≈ 1.645 for 90% confidence." },
      { id:"u6q9", q:"A 99% confidence interval compared to a 95% one (same data) is:", choices:{A:"centered differently", B:"narrower", C:"the same width", D:"wider"}, answer:"D", explanation:"Higher confidence requires a larger z*, producing a wider interval." },
      { id:"u6q10", q:"With p̂ = 0.5, n = 100, and z* = 1.96, the margin of error is closest to:", choices:{A:"0.02", B:"0.098", C:"0.05", D:"0.196"}, answer:"B", explanation:"ME = 1.96·√(0.25/100) = 1.96·0.05 = 0.098." },
      { id:"u6q11", q:"The conditions to perform inference for a proportion are:", choices:{A:"Random, 10%, and Large Counts", B:"Normal population and n ≥ 30", C:"Independence only", D:"p = 0.5"}, answer:"A", explanation:"One-proportion inference needs Random sampling, the 10% condition, and Large Counts (successes and failures ≥ 10)." },
      { id:"u6q12", q:"For a confidence interval for p, the Large Counts condition uses:", choices:{A:"p̂ ≥ 0.5", B:"np ≥ 10 and n(1-p) ≥ 10", C:"np̂ ≥ 10 and n(1-p̂) ≥ 10", D:"n ≥ 30"}, answer:"C", explanation:"In a CI (p unknown) we check np̂ and n(1-p̂) are each at least 10." },
      { id:"u6q13", q:"In a significance test for p, the null hypothesis has the form:", choices:{A:"H₀: p = p₀", B:"H₀: x̄ = μ", C:"H₀: p ≠ p₀", D:"H₀: p̂ = p₀"}, answer:"A", explanation:"The null states a specific value for the parameter: H₀: p = p₀." },
      { id:"u6q14", q:"The standard error used in a one-proportion z-TEST uses:", choices:{A:"p̂", B:"0.5 always", C:"σ", D:"the hypothesized p₀"}, answer:"D", explanation:"A significance test uses the null value p₀ in the SE: √(p₀(1-p₀)/n)." },
      { id:"u6q15", q:"A P-value is:", choices:{A:"the probability the null hypothesis is true", B:"the significance level", C:"the probability of a result at least as extreme as observed, assuming H₀ is true", D:"the probability of a Type I error in general"}, answer:"C", explanation:"The P-value is computed assuming H₀ true: P(statistic as or more extreme than observed)." },
      { id:"u6q16", q:"A small P-value provides evidence:", choices:{A:"that the sample is biased", B:"that n is too small", C:"for the null hypothesis", D:"against the null hypothesis"}, answer:"D", explanation:"Small P-values indicate the data would be unlikely if H₀ were true, so they argue against H₀." },
      { id:"u6q17", q:"If P-value ≤ α, the decision is to:", choices:{A:"increase the sample", B:"reject H₀", C:"fail to reject H₀", D:"accept H₀"}, answer:"B", explanation:"When the P-value is at most the significance level, we reject the null hypothesis." },
      { id:"u6q18", q:"If P-value > α, we:", choices:{A:"reject H₀", B:"commit a Type I error", C:"fail to reject H₀", D:"prove H₀ true"}, answer:"C", explanation:"A P-value above α means insufficient evidence to reject H₀ (we never 'accept'/'prove' it)." },
      { id:"u6q19", q:"A Type I error is:", choices:{A:"failing to reject H₀ when it is false", B:"rejecting H₀ when it is actually true", C:"choosing the wrong sample", D:"using the wrong formula"}, answer:"B", explanation:"Type I = false positive: rejecting a true null hypothesis." },
      { id:"u6q20", q:"A Type II error is:", choices:{A:"a biased sample", B:"failing to reject a false H₀", C:"a calculation mistake", D:"rejecting a true H₀"}, answer:"B", explanation:"Type II = false negative: failing to reject H₀ when the alternative is actually true." },
      { id:"u6q21", q:"The probability of a Type I error equals:", choices:{A:"the power", B:"the significance level α", C:"the P-value", D:"β"}, answer:"B", explanation:"α is the probability of a Type I error (rejecting a true null)." },
      { id:"u6q22", q:"The power of a test is:", choices:{A:"1 - α", B:"the probability of correctly rejecting a false H₀", C:"the probability of a Type I error", D:"the P-value"}, answer:"B", explanation:"Power = P(reject H₀ | H₀ false) = 1 - β." },
      { id:"u6q23", q:"Power increases when:", choices:{A:"the effect size decreases", B:"α decreases", C:"the sample size increases", D:"variability increases"}, answer:"C", explanation:"Larger samples (and larger α, larger effect, less variability) raise power; here, larger n." },
      { id:"u6q24", q:"Decreasing α from 0.05 to 0.01 will:", choices:{A:"increase the chance of a Type I error", B:"decrease power (raise the chance of a Type II error)", C:"increase power", D:"have no effect on errors"}, answer:"B", explanation:"A stricter α reduces Type I risk but makes rejection harder, lowering power and raising Type II risk." },
      { id:"u6q25", q:"A two-sided alternative hypothesis for a proportion is written:", choices:{A:"Hₐ: p ≠ p₀", B:"Hₐ: p < p₀", C:"Hₐ: p̂ ≠ p₀", D:"Hₐ: p > p₀"}, answer:"A", explanation:"A two-sided test uses Hₐ: p ≠ p₀." },
      { id:"u6q26", q:"If a 95% CI for p is (0.42, 0.58), a two-sided test of H₀: p = 0.50 at α = 0.05 would:", choices:{A:"require more data", B:"be inconclusive", C:"reject H₀", D:"fail to reject H₀"}, answer:"D", explanation:"Since 0.50 lies inside the interval, we fail to reject H₀ at the corresponding level." },
      { id:"u6q27", q:"If a 95% CI for p is (0.55, 0.65), a two-sided test of H₀: p = 0.50 at α=0.05 would:", choices:{A:"reject H₀", B:"accept H₀", C:"need a one-sided test", D:"fail to reject H₀"}, answer:"A", explanation:"0.50 is outside the interval, so we reject H₀ at α = 0.05." },
      { id:"u6q28", q:"To estimate p with 95% confidence and ME = 0.03 using p = 0.5, the required n is closest to:", choices:{A:"500", B:"385", C:"1068", D:"2401"}, answer:"C", explanation:"n = (z*/ME)²·p(1-p) = (1.96/0.03)²·0.25 ≈ 1067.1, round up to 1068." },
      { id:"u6q29", q:"When no prior estimate of p is available for sample-size planning, use:", choices:{A:"p = 0", B:"p = 1", C:"p = 0.1", D:"p = 0.5"}, answer:"D", explanation:"p = 0.5 maximizes p(1-p), giving the most conservative (largest) required sample size." },
      { id:"u6q30", q:"The point estimate for the population proportion is:", choices:{A:"p̂ = x/n", B:"p", C:"the critical value", D:"the margin of error"}, answer:"A", explanation:"p̂ = (number of successes)/(sample size) estimates p." },
      { id:"u6q31", q:"A two-sample z-test for proportions compares:", choices:{A:"two population proportions p₁ and p₂", B:"variances", C:"two population means", D:"a mean and a proportion"}, answer:"A", explanation:"It tests whether two population proportions differ." },
      { id:"u6q32", q:"In a two-proportion z-TEST, the combined (pooled) proportion is used because:", choices:{A:"the null assumes p₁ = p₂", B:"it removes bias", C:"it increases power artificially", D:"the samples are dependent"}, answer:"A", explanation:"Under H₀: p₁ = p₂, pooling the successes gives a single best estimate of the common proportion." },
      { id:"u6q33", q:"The hypotheses for comparing two proportions (two-sided) are:", choices:{A:"H₀: p₁ = p₂ vs Hₐ: p₁ ≠ p₂", B:"H₀: μ₁ = μ₂", C:"H₀: p̂₁ = p̂₂", D:"H₀: p₁ ≠ p₂"}, answer:"A", explanation:"Compare population proportions: null of equality vs two-sided alternative." },
      { id:"u6q34", q:"For a two-proportion z-INTERVAL, the standard error:", choices:{A:"uses σ", B:"always pools the proportions", C:"is NOT pooled; it uses each p̂ separately", D:"equals zero"}, answer:"C", explanation:"Confidence intervals don't assume equality, so the SE keeps the two sample proportions separate." },
      { id:"u6q35", q:"A confidence interval for p₁ - p₂ that contains 0 suggests:", choices:{A:"the test is invalid", B:"p₁ = 1", C:"a significant difference", D:"no significant difference between the proportions"}, answer:"D", explanation:"If 0 is a plausible value for the difference, the proportions may be equal — no significant difference." },
      { id:"u6q36", q:"Statistical significance means:", choices:{A:"the result is important in real life", B:"the sample is large", C:"the null is proven false", D:"the result is unlikely to be due to chance alone"}, answer:"D", explanation:"Significance addresses chance, not practical importance; a tiny effect can be significant with large n." },
      { id:"u6q37", q:"A result can be statistically significant but not practically important when:", choices:{A:"the sample size is very large and the effect is tiny", B:"α is very large", C:"the P-value is large", D:"the CI is wide"}, answer:"A", explanation:"Huge samples can detect trivial effects, yielding significance without practical importance." },
      { id:"u6q38", q:"Increasing the confidence level while keeping n fixed makes the interval:", choices:{A:"centered elsewhere", B:"unchanged", C:"wider", D:"narrower"}, answer:"C", explanation:"Greater confidence needs a larger critical value, so the interval widens." },
      { id:"u6q39", q:"Which change makes a confidence interval narrower?", choices:{A:"Higher confidence level", B:"Larger sample size", C:"More variability", D:"Smaller sample size"}, answer:"B", explanation:"Bigger n lowers the standard error, narrowing the interval." },
      { id:"u6q40", q:"If the Random condition is violated, the inference results are:", choices:{A:"still valid", B:"not trustworthy (generalization is compromised)", C:"automatically significant", D:"unbiased"}, answer:"B", explanation:"Without randomness, the sampling-distribution basis for inference breaks down and conclusions are unreliable." },
      { id:"u6q41", q:"A 90% confidence interval for p is (0.48, 0.56). The point estimate p̂ is:", choices:{A:"0.52", B:"0.04", C:"0.56", D:"0.48"}, answer:"A", explanation:"The estimate is the midpoint: (0.48+0.56)/2 = 0.52." },
      { id:"u6q42", q:"The margin of error of the interval (0.48, 0.56) is:", choices:{A:"0.08", B:"0.52", C:"0.04", D:"0.02"}, answer:"C", explanation:"ME = half the width = (0.56-0.48)/2 = 0.04." },
      { id:"u6q43", q:"A one-sided test found P = 0.03. At α = 0.05 you:", choices:{A:"fail to reject H₀", B:"need a CI", C:"reject H₀", D:"accept H₀"}, answer:"C", explanation:"0.03 ≤ 0.05, so reject H₀." },
      { id:"u6q44", q:"A test found P = 0.12 at α = 0.05. The conclusion is:", choices:{A:"fail to reject H₀; insufficient evidence", B:"reject H₀", C:"H₀ is true", D:"Hₐ is true"}, answer:"A", explanation:"0.12 > 0.05, so we fail to reject — not enough evidence for Hₐ." },
      { id:"u6q45", q:"'Failing to reject H₀' means:", choices:{A:"there is not enough evidence against H₀", B:"H₀ is proven true", C:"a Type I error occurred", D:"Hₐ is false"}, answer:"A", explanation:"We never prove the null; we simply lack sufficient evidence to reject it." },
      { id:"u6q46", q:"The confidence level corresponds to which long-run idea?", choices:{A:"The probability H₀ is true", B:"The percent of intervals (from repeated samples) that capture the parameter", C:"The sample success rate", D:"The percent of data captured"}, answer:"B", explanation:"A C% confidence level means C% of intervals built this way would contain the true parameter over many samples." },
      { id:"u6q47", q:"A larger effect size, all else equal, gives the test:", choices:{A:"less power", B:"a larger Type I error", C:"no change in power", D:"more power"}, answer:"D", explanation:"Bigger true differences are easier to detect, increasing power." },
      { id:"u6q48", q:"Which is required for a two-proportion procedure's Large Counts in a CI?", choices:{A:"equal sample sizes", B:"p₁ = p₂", C:"Each group has at least 10 successes and 10 failures", D:"n ≥ 30 total"}, answer:"C", explanation:"Both samples must have at least 10 successes and 10 failures for the normal approximation." },
      { id:"u6q49", q:"A confidence interval method that captures the parameter 95% of the time has confidence level:", choices:{A:"90%", B:"95%", C:"99%", D:"5%"}, answer:"B", explanation:"The capture rate is exactly the confidence level — here 95%." },
      { id:"u6q50", q:"Doubling n in a proportion CI changes the margin of error by a factor of about:", choices:{A:"1/2", B:"2", C:"√2", D:"1/√2"}, answer:"D", explanation:"ME ∝ 1/√n; doubling n divides the ME by √2." },
    ]
  },
  {
    key: "apstat-u7", label: "U7: Inference for Means", icon: "📏", color: "#0891b2", bg: "#ecfeff",
    questions: [
      { id:"u7q1", q:"Inference for a population mean uses the ____ distribution when σ is unknown.", choices:{A:"t", B:"standard normal (z)", C:"chi-square", D:"binomial"}, answer:"A", explanation:"When σ is unknown (the usual case) and we estimate it with s, we use the t-distribution." },
      { id:"u7q2", q:"The t-distribution compared to the standard normal is:", choices:{A:"skewed right", B:"identical", C:"more spread out, with heavier tails", D:"narrower"}, answer:"C", explanation:"t-distributions have more spread/heavier tails to account for extra uncertainty from estimating σ." },
      { id:"u7q3", q:"As the degrees of freedom increase, the t-distribution:", choices:{A:"gets wider", B:"becomes more skewed", C:"becomes uniform", D:"approaches the standard normal"}, answer:"D", explanation:"With more df, t looks increasingly like the standard normal (z)." },
      { id:"u7q4", q:"For a one-sample t-procedure with sample size n, the degrees of freedom are:", choices:{A:"2n", B:"n - 2", C:"n", D:"n - 1"}, answer:"D", explanation:"One-sample t uses df = n - 1." },
      { id:"u7q5", q:"The standard error of x̄ when σ is unknown is:", choices:{A:"s/n", B:"s/√n", C:"s·√n", D:"σ/√n"}, answer:"B", explanation:"Estimate the SE of the mean with s/√n." },
      { id:"u7q6", q:"With x̄ = 50, s = 8, n = 16, and t* = 2.131, the margin of error is closest to:", choices:{A:"4.26", B:"1.07", C:"8.0", D:"2.13"}, answer:"A", explanation:"ME = t*·s/√n = 2.131·8/4 = 2.131·2 = 4.26." },
      { id:"u7q7", q:"A one-sample t-interval for a mean has the form:", choices:{A:"p̂ ± z*·SE", B:"x̄ ± t*·(s/√n)", C:"μ ± s", D:"x̄ ± z*·(σ/√n)"}, answer:"B", explanation:"CI for a mean: x̄ ± t*·(s/√n)." },
      { id:"u7q8", q:"The conditions for one-sample t inference are:", choices:{A:"p = 0.5", B:"Random, 10% (independence), and Normal/large sample", C:"np ≥ 10", D:"σ known"}, answer:"B", explanation:"Need randomness, independence (10% condition), and either a normal population or large enough n (CLT)." },
      { id:"u7q9", q:"If the sample size is small and the population is clearly skewed with outliers, t-procedures are:", choices:{A:"unaffected", B:"always exact", C:"safe to use", D:"not appropriate"}, answer:"D", explanation:"t-procedures require approximate normality; small skewed samples with outliers violate that." },
      { id:"u7q10", q:"For a paired t-test (matched pairs), you analyze:", choices:{A:"the two samples separately", B:"the proportions", C:"the differences within each pair", D:"the pooled variance"}, answer:"C", explanation:"Matched-pairs inference works with the single list of within-pair differences." },
      { id:"u7q11", q:"A paired design is appropriate when:", choices:{A:"each subject is measured twice or subjects are naturally paired", B:"two independent groups are compared", C:"there is one sample of proportions", D:"the data are categorical"}, answer:"A", explanation:"Pairing (before/after, twins, matched units) ties observations together, so we analyze differences." },
      { id:"u7q12", q:"The null hypothesis for a one-sample mean test is:", choices:{A:"H₀: μ = μ₀", B:"H₀: μ ≠ μ₀", C:"H₀: x̄ = μ₀", D:"H₀: p = p₀"}, answer:"A", explanation:"The null states a specific value for the population mean: μ = μ₀." },
      { id:"u7q13", q:"With x̄ = 52, μ₀ = 50, s = 8, n = 16, the t statistic is:", choices:{A:"2.0", B:"4.0", C:"1.0", D:"0.25"}, answer:"C", explanation:"t = (x̄-μ₀)/(s/√n) = (52-50)/(8/4) = 2/2 = 1.0." },
      { id:"u7q14", q:"A two-sample t-test compares:", choices:{A:"two population means from independent samples", B:"two proportions", C:"variances", D:"a mean to a fixed value"}, answer:"A", explanation:"It tests whether two independent population means differ." },
      { id:"u7q15", q:"Two-sample t-procedures (unpooled) do NOT require:", choices:{A:"equal population variances", B:"randomness", C:"independent samples", D:"approximate normality of each group"}, answer:"A", explanation:"The standard (unpooled) two-sample t does not assume equal variances." },
      { id:"u7q16", q:"The hypotheses for comparing two means (two-sided) are:", choices:{A:"H₀: p₁ = p₂", B:"H₀: x̄₁ = x̄₂", C:"H₀: μ₁ = μ₂ vs Hₐ: μ₁ ≠ μ₂", D:"H₀: μ₁ ≠ μ₂"}, answer:"C", explanation:"Compare population means: equality null vs two-sided alternative." },
      { id:"u7q17", q:"A confidence interval for μ₁ - μ₂ that contains 0 indicates:", choices:{A:"the test is invalid", B:"no significant difference in means", C:"μ₁ = 0", D:"a significant difference in means"}, answer:"B", explanation:"If 0 is plausible for the difference, the means may be equal — no significant difference." },
      { id:"u7q18", q:"Increasing the sample size in a t-interval generally:", choices:{A:"has no effect", B:"shifts the center to 0", C:"widens the interval", D:"narrows the interval"}, answer:"D", explanation:"Larger n lowers s/√n and increases df (smaller t*), narrowing the interval." },
      { id:"u7q19", q:"A 95% confidence interval for μ is (12.4, 15.6). The sample mean is:", choices:{A:"14.0", B:"1.6", C:"12.4", D:"15.6"}, answer:"A", explanation:"Midpoint = (12.4+15.6)/2 = 14.0." },
      { id:"u7q20", q:"The margin of error for the interval (12.4, 15.6) is:", choices:{A:"14.0", B:"3.2", C:"1.6", D:"0.8"}, answer:"C", explanation:"Half-width = (15.6-12.4)/2 = 1.6." },
      { id:"u7q21", q:"A P-value of 0.002 in a t-test at α = 0.05 leads to:", choices:{A:"no decision", B:"fail to reject H₀", C:"accept H₀", D:"reject H₀"}, answer:"D", explanation:"0.002 ≤ 0.05, strong evidence to reject the null." },
      { id:"u7q22", q:"A larger t* (critical value) is used for:", choices:{A:"larger samples", B:"lower confidence levels", C:"normal populations only", D:"higher confidence levels"}, answer:"D", explanation:"Higher confidence requires a larger critical value, widening the interval." },
      { id:"u7q23", q:"The t-procedures are considered 'robust', meaning:", choices:{A:"they never make errors", B:"they only apply to proportions", C:"they work fairly well even when normality is mildly violated, especially for larger n", D:"they require σ to be known"}, answer:"C", explanation:"t-procedures tolerate moderate departures from normality, more so as n grows." },
      { id:"u7q24", q:"For matched pairs with n pairs, the degrees of freedom are:", choices:{A:"n - 2", B:"2n - 2", C:"n", D:"n - 1"}, answer:"D", explanation:"Paired t works on n differences, so df = n - 1." },
      { id:"u7q25", q:"Which scenario calls for a paired (not two-sample) t-procedure?", choices:{A:"Comparing two separate random groups", B:"Comparing test scores of the same students before and after a course", C:"Estimating one mean", D:"Comparing two proportions"}, answer:"B", explanation:"Before/after on the same individuals creates natural pairs, so use a paired procedure." },
      { id:"u7q26", q:"Failing to check the Normal/large-sample condition can make a t-test's:", choices:{A:"sample larger", B:"mean biased", C:"P-value unreliable", D:"degrees of freedom negative"}, answer:"C", explanation:"If normality fails badly with small n, the t-model is wrong and the P-value can't be trusted." },
      { id:"u7q27", q:"Which increases the power of a t-test?", choices:{A:"Lower α", B:"More variability", C:"A larger sample size", D:"Smaller effect size"}, answer:"C", explanation:"Bigger samples increase power (as do larger α, larger effects, and less variability)." },
      { id:"u7q28", q:"The center of a one-sample t-interval is:", choices:{A:"the population mean μ", B:"zero", C:"the standard error", D:"the sample mean x̄"}, answer:"D", explanation:"A t-interval is centered at the point estimate x̄." },
      { id:"u7q29", q:"Compared to a z-interval (σ known), a t-interval (σ unknown, same data and confidence) is:", choices:{A:"the same", B:"wider", C:"narrower", D:"impossible"}, answer:"B", explanation:"t* exceeds z*, so the t-interval is wider, reflecting extra uncertainty in estimating σ." },
      { id:"u7q30", q:"A two-sided t-test gives P = 0.08. A 95% CI for the mean difference would:", choices:{A:"be centered at 0", B:"have width 0", C:"contain 0", D:"exclude 0"}, answer:"C", explanation:"Since P > 0.05, we don't reject H₀, so the 95% CI for the difference includes 0." },
      { id:"u7q31", q:"x̄ = 104, μ₀ = 100, s = 12, n = 36. The t statistic equals:", choices:{A:"4.0", B:"2.0", C:"0.33", D:"1.0"}, answer:"B", explanation:"t = (104-100)/(12/√36) = 4/(12/6) = 4/2 = 2.0." },
      { id:"u7q32", q:"Degrees of freedom for this one-sample test (n = 36) are:", choices:{A:"34", B:"36", C:"35", D:"72"}, answer:"C", explanation:"df = n - 1 = 35." },
      { id:"u7q33", q:"A confidence interval for a mean does NOT depend on:", choices:{A:"the confidence level", B:"the sample mean", C:"the sample size", D:"the population size (given 10% condition)"}, answer:"D", explanation:"Given the 10% condition, population size has essentially no effect on the interval." },
      { id:"u7q34", q:"If a t-interval for μ is entirely above 0, then a test of H₀: μ = 0 (two-sided) would:", choices:{A:"reject H₀", B:"be invalid", C:"accept H₀", D:"fail to reject H₀"}, answer:"A", explanation:"If 0 is not in the interval, the corresponding two-sided test rejects H₀." },
      { id:"u7q35", q:"The most important graph to check before a small-sample t-procedure is:", choices:{A:"a dotplot/boxplot/histogram of the sample to assess normality and outliers", B:"a scatterplot", C:"a residual plot", D:"a segmented bar chart"}, answer:"A", explanation:"Graphing the sample checks the Normal condition (shape, skew, outliers) for small n." },
      { id:"u7q36", q:"A 'statistically significant' difference in means means:", choices:{A:"the difference is large in practice", B:"the sample is biased", C:"the difference is unlikely under H₀ of no difference", D:"μ₁ = μ₂"}, answer:"C", explanation:"Significance means the observed difference would be unlikely if the means were truly equal." },
      { id:"u7q37", q:"A wider confidence interval reflects:", choices:{A:"more uncertainty about the parameter", B:"more precision", C:"a larger sample", D:"a lower confidence level"}, answer:"A", explanation:"Wider intervals indicate greater uncertainty (less precision)." },
      { id:"u7q38", q:"For the difference of two means with independent samples, variances:", choices:{A:"subtract", B:"add", C:"are ignored", D:"multiply"}, answer:"B", explanation:"SE of x̄₁ - x̄₂ combines variances by adding them: √(s₁²/n₁ + s₂²/n₂)." },
      { id:"u7q39", q:"The conservative degrees of freedom for a two-sample t (by hand) use:", choices:{A:"n₁·n₂", B:"the smaller of n₁-1 and n₂-1", C:"n₁ + n₂", D:"always 30"}, answer:"B", explanation:"A common by-hand approach uses df = min(n₁-1, n₂-1) as a conservative choice." },
      { id:"u7q40", q:"A researcher wants a narrower interval without lowering confidence. She should:", choices:{A:"increase variability", B:"collect a larger sample", C:"use a smaller sample", D:"raise the confidence level"}, answer:"B", explanation:"Increasing n reduces the standard error and narrows the interval while keeping confidence fixed." },
      { id:"u7q41", q:"A P-value just above α (e.g., 0.051 at α = 0.05) means:", choices:{A:"reject H₀", B:"fail to reject H₀, but it's a close call", C:"the effect is large", D:"H₀ is true"}, answer:"B", explanation:"Since 0.051 > 0.05, we narrowly fail to reject; significance is borderline." },
      { id:"u7q42", q:"The assumption of independence between two samples is violated if:", choices:{A:"the samples are random", B:"the same subjects appear in both groups", C:"sample sizes differ", D:"variances differ"}, answer:"B", explanation:"Shared subjects create dependence; that situation calls for a paired procedure instead." },
      { id:"u7q43", q:"Reducing α makes a Type II error:", choices:{A:"less likely", B:"more likely", C:"impossible", D:"equal to α"}, answer:"B", explanation:"A smaller α makes rejection harder, increasing the chance of a Type II error (lower power)." },
      { id:"u7q44", q:"A correct interpretation of a 95% CI (10, 14) for μ is:", choices:{A:"We are 95% confident the population mean is between 10 and 14", B:"95% of data are between 10 and 14", C:"μ equals 12 exactly", D:"There's a 95% chance x̄ is in (10,14)"}, answer:"A", explanation:"We're 95% confident the interval captures the true population mean." },
      { id:"u7q45", q:"The point estimate in a two-sample mean problem is:", choices:{A:"n₁ - n₂", B:"μ₁ - μ₂", C:"x̄₁ - x̄₂", D:"s₁ - s₂"}, answer:"C", explanation:"The difference of sample means estimates μ₁ - μ₂." },
      { id:"u7q46", q:"If a 90% and 95% CI are built from the same data, the 95% one is:", choices:{A:"centered differently", B:"narrower", C:"wider", D:"identical"}, answer:"C", explanation:"Higher confidence uses a larger t*, producing a wider interval." },
      { id:"u7q47", q:"When σ is genuinely known (rare), inference for a mean uses:", choices:{A:"the binomial", B:"a z-procedure", C:"chi-square", D:"a t-procedure"}, answer:"B", explanation:"Known σ allows the z-distribution; unknown σ requires t." },
      { id:"u7q48", q:"Outliers in a small sample affect a t-test most by:", choices:{A:"changing the degrees of freedom", B:"distorting x̄ and s, undermining the Normal condition", C:"changing α", D:"having no effect"}, answer:"B", explanation:"Outliers shift the mean and inflate s, and they violate the normality requirement for small n." },
      { id:"u7q49", q:"A 99% CI for a difference of means is (−2, 8). At the 1% level, the two-sided test:", choices:{A:"rejects H₀", B:"accepts Hₐ", C:"fails to reject H₀: μ₁ = μ₂ (0 is inside)", D:"is invalid"}, answer:"C", explanation:"Because 0 lies inside the 99% interval, the matching test fails to reject equality." },
      { id:"u7q50", q:"The main reason to use t instead of z for means is:", choices:{A:"means are categorical", B:"t has lighter tails", C:"to make intervals narrower", D:"we estimate σ with s, adding uncertainty"}, answer:"D", explanation:"Using s in place of an unknown σ adds uncertainty, which the heavier-tailed t-distribution accounts for." },
    ]
  },
  {
    key: "apstat-u8", label: "U8: Chi-Square Tests", icon: "🔬", color: "#c026d3", bg: "#fdf4ff",
    questions: [
      { id:"u8q1", q:"Chi-square procedures are used for data that are:", choices:{A:"categorical (counts in categories)", B:"paired measurements", C:"continuous only", D:"quantitative"}, answer:"A", explanation:"Chi-square tests analyze counts/frequencies of categorical variables." },
      { id:"u8q2", q:"A chi-square goodness-of-fit test compares:", choices:{A:"a slope to zero", B:"two means", C:"two proportions only", D:"observed counts to expected counts from a claimed distribution"}, answer:"D", explanation:"GOF tests whether one categorical variable's observed counts match a hypothesized distribution." },
      { id:"u8q3", q:"The chi-square statistic is computed as:", choices:{A:"Σ (Observed - Expected)² / Expected", B:"Σ O²/E²", C:"Σ (O - E)", D:"(O - E)/√E"}, answer:"A", explanation:"χ² = Σ (O - E)²/E, summed over all cells." },
      { id:"u8q4", q:"Chi-square values are always:", choices:{A:"between -1 and 1", B:"non-negative", C:"negative", D:"less than 1"}, answer:"B", explanation:"Because each term squares (O - E), χ² ≥ 0." },
      { id:"u8q5", q:"A large chi-square statistic indicates:", choices:{A:"a small sample", B:"observed counts are close to expected", C:"the variables are quantitative", D:"observed counts differ substantially from expected"}, answer:"D", explanation:"Large χ² means big discrepancies between observed and expected counts — evidence against H₀." },
      { id:"u8q6", q:"For a goodness-of-fit test with k categories, the degrees of freedom are:", choices:{A:"k - 1", B:"k", C:"k - 2", D:"n - 1"}, answer:"A", explanation:"GOF df = (number of categories) - 1." },
      { id:"u8q7", q:"A goodness-of-fit test has 6 categories. Its degrees of freedom are:", choices:{A:"4", B:"7", C:"6", D:"5"}, answer:"D", explanation:"df = k - 1 = 6 - 1 = 5." },
      { id:"u8q8", q:"In a GOF test, an expected count is computed as:", choices:{A:"(hypothesized proportion) × (sample size n)", B:"observed/n", C:"n/k always", D:"(O - E)²"}, answer:"A", explanation:"Expected count = n × (proportion specified by H₀ for that category)." },
      { id:"u8q9", q:"If H₀ claims a category has proportion 0.25 and n = 200, the expected count is:", choices:{A:"100", B:"25", C:"0.25", D:"50"}, answer:"D", explanation:"Expected = 200 × 0.25 = 50." },
      { id:"u8q10", q:"The chi-square distribution is:", choices:{A:"left-skewed", B:"right-skewed, becoming more symmetric as df increases", C:"symmetric", D:"uniform"}, answer:"B", explanation:"Chi-square distributions are skewed right and approach symmetry as df grows." },
      { id:"u8q11", q:"The Large Counts condition for chi-square requires:", choices:{A:"n ≥ 30", B:"all expected counts ≥ 5", C:"all observed counts ≥ 10", D:"np ≥ 10"}, answer:"B", explanation:"Each expected cell count should be at least 5 for the chi-square approximation." },
      { id:"u8q12", q:"A chi-square test for homogeneity compares:", choices:{A:"the distribution of one categorical variable across two or more populations/groups", B:"two means", C:"one proportion to a value", D:"a slope"}, answer:"A", explanation:"Homogeneity tests whether several populations share the same distribution of a categorical variable." },
      { id:"u8q13", q:"A chi-square test for independence (association) uses data from:", choices:{A:"quantitative measurements", B:"matched pairs", C:"two separate populations", D:"a single sample classified by two categorical variables"}, answer:"D", explanation:"Independence tests use one sample cross-classified by two categorical variables." },
      { id:"u8q14", q:"For a two-way table with r rows and c columns, the degrees of freedom are:", choices:{A:"r + c", B:"rc - 1", C:"n - 1", D:"(r-1)(c-1)"}, answer:"D", explanation:"df = (r - 1)(c - 1) for homogeneity/independence tests." },
      { id:"u8q15", q:"A 3×4 two-way table has how many degrees of freedom?", choices:{A:"11", B:"6", C:"7", D:"12"}, answer:"B", explanation:"(3-1)(4-1) = 2×3 = 6." },
      { id:"u8q16", q:"In a two-way table, an expected cell count equals:", choices:{A:"row total + column total", B:"(row total × column total) / grand total", C:"observed - row total", D:"grand total / cells"}, answer:"B", explanation:"Expected = (row total)(column total)/(grand total)." },
      { id:"u8q17", q:"A cell has row total 40, column total 50, grand total 200. Its expected count is:", choices:{A:"5", B:"90", C:"20", D:"10"}, answer:"D", explanation:"Expected = 40×50/200 = 2000/200 = 10." },
      { id:"u8q18", q:"The null hypothesis in a test for independence states that the two variables are:", choices:{A:"normally distributed", B:"equal in mean", C:"independent (not associated)", D:"associated"}, answer:"C", explanation:"H₀: the two categorical variables are independent (no association)." },
      { id:"u8q19", q:"The null hypothesis in a test for homogeneity states that:", choices:{A:"the means are equal", B:"the distributions are the same across all populations", C:"there is an association", D:"the slope is 0"}, answer:"B", explanation:"H₀: all populations have the same distribution of the categorical variable." },
      { id:"u8q20", q:"A small chi-square statistic (large P-value) means:", choices:{A:"observed counts are close to expected; fail to reject H₀", B:"the variables are associated", C:"reject H₀", D:"strong evidence against H₀"}, answer:"A", explanation:"Small χ² ⇒ good agreement with H₀ ⇒ large P-value ⇒ fail to reject." },
      { id:"u8q21", q:"If χ² = 12.5 with df = 4 gives P = 0.014, then at α = 0.05 you:", choices:{A:"fail to reject H₀", B:"cannot decide", C:"accept H₀", D:"reject H₀"}, answer:"D", explanation:"0.014 ≤ 0.05, so reject the null." },
      { id:"u8q22", q:"Each term (O - E)²/E in the chi-square sum measures:", choices:{A:"how far one cell's observed count is from its expected count, relative to expected", B:"the mean", C:"the slope", D:"the correlation"}, answer:"A", explanation:"Each component quantifies a single cell's standardized squared discrepancy." },
      { id:"u8q23", q:"Which test would you use to see if die rolls follow a uniform distribution?", choices:{A:"Regression t-test", B:"Two-sample t", C:"Test for independence", D:"Goodness-of-fit"}, answer:"D", explanation:"Comparing observed roll counts to a claimed uniform distribution is a goodness-of-fit test." },
      { id:"u8q24", q:"Which test examines whether two categorical variables measured on one sample are related?", choices:{A:"Paired t-test", B:"Test for independence", C:"Two-proportion z-test", D:"Goodness-of-fit"}, answer:"B", explanation:"One sample, two categorical variables, checking association ⇒ chi-square test for independence." },
      { id:"u8q25", q:"Increasing the discrepancy between observed and expected counts:", choices:{A:"increases χ² and decreases the P-value", B:"increases the P-value", C:"has no effect", D:"decreases χ²"}, answer:"A", explanation:"Bigger O−E gaps inflate χ², pushing the P-value down (stronger evidence against H₀)." },
      { id:"u8q26", q:"If an expected count is below 5, the appropriate action is to:", choices:{A:"note the condition is not met and interpret cautiously (or combine categories)", B:"ignore it", C:"use a z-test", D:"increase α"}, answer:"A", explanation:"Failing the expected-count condition undermines the approximation; combine cells or use caution." },
      { id:"u8q27", q:"The largest contributor to χ² is the cell with:", choices:{A:"the biggest (O - E)²/E value", B:"the largest row total", C:"the smallest expected count", D:"the largest observed count"}, answer:"A", explanation:"The cell with the greatest standardized squared difference contributes most." },
      { id:"u8q28", q:"For a goodness-of-fit test with proportions 0.5, 0.3, 0.2 and n = 100, the expected counts are:", choices:{A:"100, 100, 100", B:"5, 3, 2", C:"50, 30, 20", D:"33, 33, 33"}, answer:"C", explanation:"Multiply each proportion by n: 50, 30, 20." },
      { id:"u8q29", q:"Chi-square tests are ____ tests, examining the right tail only.", choices:{A:"lower-tail", B:"two-sided", C:"paired", D:"one-sided (upper tail)"}, answer:"D", explanation:"Because χ² measures squared discrepancies, only large values are extreme — an upper-tail test." },
      { id:"u8q30", q:"A test for homogeneity uses data collected as:", choices:{A:"one sample classified two ways", B:"a regression", C:"matched pairs", D:"separate random samples from each population"}, answer:"D", explanation:"Homogeneity compares independent samples drawn from each population/group." },
      { id:"u8q31", q:"As degrees of freedom increase, the mean of a chi-square distribution:", choices:{A:"increases (mean equals df)", B:"stays at 0", C:"decreases", D:"equals 1"}, answer:"A", explanation:"The mean of a chi-square distribution equals its degrees of freedom." },
      { id:"u8q32", q:"A goodness-of-fit test fails to reject H₀. The best conclusion is:", choices:{A:"the claimed distribution is proven true", B:"the variables are associated", C:"the data are consistent with the claimed distribution", D:"the means are equal"}, answer:"C", explanation:"We can only say the data are consistent with H₀, not that it's proven." },
      { id:"u8q33", q:"Which is NOT a chi-square procedure?", choices:{A:"Goodness-of-fit", B:"Test for homogeneity", C:"Test for independence", D:"Two-sample t-test"}, answer:"D", explanation:"The two-sample t-test is for means, not categorical counts." },
      { id:"u8q34", q:"The expected counts in a chi-square test are based on:", choices:{A:"the alternative hypothesis", B:"what H₀ predicts", C:"random guessing", D:"the observed data directly"}, answer:"B", explanation:"Expected counts come from the model specified by the null hypothesis." },
      { id:"u8q35", q:"A cell has observed 30 and expected 20. Its contribution to χ² is:", choices:{A:"5.0", B:"0.5", C:"10.0", D:"2.0"}, answer:"A", explanation:"(30-20)²/20 = 100/20 = 5.0." },
      { id:"u8q36", q:"Observed [40, 35, 25] vs expected [30, 30, 40]. The chi-square statistic is closest to:", choices:{A:"4.5", B:"9.8", C:"15.0", D:"6.0"}, answer:"B", explanation:"(10²/30)+(5²/30)+(15²/40)=3.33+0.83+5.63≈9.8." },
      { id:"u8q37", q:"A test for independence with a 2×2 table has degrees of freedom:", choices:{A:"3", B:"2", C:"1", D:"4"}, answer:"C", explanation:"(2-1)(2-1) = 1." },
      { id:"u8q38", q:"A very small P-value in a test for independence means:", choices:{A:"the means differ", B:"the variables are independent", C:"strong evidence the variables are associated", D:"a small sample"}, answer:"C", explanation:"A small P-value rejects independence, supporting an association between the variables." },
      { id:"u8q39", q:"Chi-square inference requires which sampling condition?", choices:{A:"Random sampling/assignment and independence", B:"Normal population", C:"σ known", D:"p = 0.5"}, answer:"A", explanation:"Like other inference, chi-square needs randomness and independence (plus the expected-count condition)." },
      { id:"u8q40", q:"Combining categories with small expected counts is done to:", choices:{A:"increase χ²", B:"meet the expected-count (≥5) condition", C:"change the hypotheses", D:"reduce the sample"}, answer:"B", explanation:"Merging sparse categories raises expected counts so the chi-square approximation is valid." },
      { id:"u8q41", q:"In a goodness-of-fit test, observed counts must be:", choices:{A:"proportions", B:"means", C:"z-scores", D:"whole-number counts, not percentages"}, answer:"D", explanation:"Chi-square uses actual counts; convert any percentages to counts first." },
      { id:"u8q42", q:"The P-value for a chi-square test is the area:", choices:{A:"in both tails", B:"under the whole curve", C:"to the right of the test statistic", D:"to the left of the statistic"}, answer:"C", explanation:"Chi-square P-values are upper-tail areas (to the right of χ²)." },
      { id:"u8q43", q:"If observed equals expected in every cell, χ² equals:", choices:{A:"the df", B:"n", C:"1", D:"0"}, answer:"D", explanation:"Each (O-E)² term is 0, so the sum is 0 — perfect agreement with H₀." },
      { id:"u8q44", q:"A chi-square test for homogeneity across 4 groups and 3 response categories has df:", choices:{A:"12", B:"6", C:"5", D:"7"}, answer:"B", explanation:"Treat as a 3×4 (or 4×3) table: (4-1)(3-1) = 3×2 = 6." },
      { id:"u8q45", q:"Which describes the relationship between χ² and the P-value?", choices:{A:"They are unrelated", B:"χ² equals the P-value", C:"Larger χ² gives a smaller P-value", D:"Larger χ² gives a larger P-value"}, answer:"C", explanation:"Bigger χ² lands further in the right tail, producing a smaller P-value." },
      { id:"u8q46", q:"After rejecting H₀ in a chi-square test, a useful follow-up is to:", choices:{A:"fit a regression line", B:"do a t-test", C:"compute a mean", D:"examine which cells had the largest components (O-E)²/E"}, answer:"D", explanation:"Inspecting the largest contributions shows where observed and expected differ most." },
      { id:"u8q47", q:"Expected counts can be non-integer values. This is:", choices:{A:"an error to be rounded away", B:"acceptable; they are theoretical averages", C:"a sign of bad data", D:"impossible"}, answer:"B", explanation:"Expected counts are theoretical and may be fractional; do not round them before computing χ²." },
      { id:"u8q48", q:"A goodness-of-fit test is essentially comparing a single categorical variable's counts to:", choices:{A:"a hypothesized model/distribution", B:"another sample", C:"two means", D:"a regression line"}, answer:"A", explanation:"GOF checks one variable's observed counts against a claimed distribution." },
      { id:"u8q49", q:"Which would NOT be analyzed with chi-square?", choices:{A:"Association between gender and major", B:"Distribution of blood types vs a claimed model", C:"Whether color preference is uniform", D:"Average height across three cities"}, answer:"D", explanation:"Average height is quantitative — use ANOVA/means methods, not chi-square." },
      { id:"u8q50", q:"The chi-square test statistic increases as:", choices:{A:"df decreases", B:"observed counts deviate more from expected", C:"the sample shrinks", D:"expected counts grow with no change in observed"}, answer:"B", explanation:"Greater observed-vs-expected discrepancies inflate the χ² statistic." },
    ]
  },
  {
    key: "apstat-u9", label: "U9: Inference for Slopes", icon: "📉", color: "#65a30d", bg: "#f7fee7",
    questions: [
      { id:"u9q1", q:"Inference for the slope of a regression line concerns the parameter:", choices:{A:"b, the sample slope", B:"the intercept only", C:"β, the true population slope", D:"r"}, answer:"C", explanation:"We do inference about the population slope β using the sample slope b as the estimate." },
      { id:"u9q2", q:"The null hypothesis for a slope t-test is usually:", choices:{A:"H₀: r = 1", B:"H₀: b = 0", C:"H₀: β ≠ 0", D:"H₀: β = 0 (no linear relationship)"}, answer:"D", explanation:"H₀: β = 0 states there is no linear relationship between x and y in the population." },
      { id:"u9q3", q:"Rejecting H₀: β = 0 provides evidence that:", choices:{A:"there is a linear relationship between x and y", B:"x causes y", C:"the slope is exactly 1", D:"r = 0"}, answer:"A", explanation:"A significant slope indicates a linear association; causation needs an experiment." },
      { id:"u9q4", q:"The test statistic for a slope is:", choices:{A:"t = b / SE(b)", B:"t = r/√n", C:"χ² = b²", D:"z = b·SE"}, answer:"A", explanation:"t = (sample slope)/(standard error of the slope), tested against a t-distribution." },
      { id:"u9q5", q:"Degrees of freedom for inference about a regression slope (one predictor) are:", choices:{A:"n - 3", B:"n - 1", C:"n - 2", D:"n"}, answer:"C", explanation:"Simple linear regression inference uses df = n - 2." },
      { id:"u9q6", q:"A regression gives b = 2.5 with SE(b) = 0.5. The t statistic is:", choices:{A:"0.2", B:"2.0", C:"5.0", D:"1.25"}, answer:"C", explanation:"t = 2.5/0.5 = 5.0." },
      { id:"u9q7", q:"A confidence interval for the slope has the form:", choices:{A:"b ± z*·SE(b)", B:"β ± t*·s", C:"r ± t*·SE", D:"b ± t*·SE(b)"}, answer:"D", explanation:"Slope CI: b ± t*·SE(b) with df = n - 2." },
      { id:"u9q8", q:"If a 95% CI for the slope is (1.2, 3.4), a two-sided test of H₀: β = 0 at α = 0.05 would:", choices:{A:"fail to reject H₀", B:"accept H₀", C:"be invalid", D:"reject H₀"}, answer:"D", explanation:"Since 0 is not in the interval, reject H₀ — evidence of a linear relationship." },
      { id:"u9q9", q:"If a 95% CI for the slope is (-0.5, 1.8), a two-sided test of H₀: β = 0 would:", choices:{A:"need more data", B:"prove β = 0", C:"fail to reject H₀", D:"reject H₀"}, answer:"C", explanation:"0 lies inside the interval, so we fail to reject H₀." },
      { id:"u9q10", q:"The conditions for regression inference are remembered by 'LINER':", choices:{A:"Linear, Identical, Numeric, Equal, Random", B:"Large, Independent, Normal, Equal, Random", C:"Linear, Independent, Normal, Equal SD, Random", D:"Linear, Independent, Normal, Exact, Random"}, answer:"C", explanation:"LINER: Linear relationship, Independent observations, Normal residuals, Equal variance, Random data." },
      { id:"u9q11", q:"The 'Linear' condition is checked using:", choices:{A:"the sample size", B:"a residual plot showing no leftover pattern", C:"the correlation only", D:"a histogram of x"}, answer:"B", explanation:"A residual plot with random scatter (no curve) supports the linearity assumption." },
      { id:"u9q12", q:"The 'Equal variance' condition means:", choices:{A:"x and y have the same variance", B:"the spread of residuals is roughly constant across x", C:"the slope equals the intercept", D:"all residuals are zero"}, answer:"B", explanation:"Residuals should show similar vertical spread for all x-values (homoscedasticity)." },
      { id:"u9q13", q:"The 'Normal' condition for slope inference refers to:", choices:{A:"the residuals being approximately normal", B:"y being uniform", C:"x being normal", D:"the slope being normal"}, answer:"A", explanation:"The residuals (responses around the line) should be approximately normal." },
      { id:"u9q14", q:"In computer regression output, the slope's t statistic and P-value test:", choices:{A:"H₀: μ = 0", B:"H₀: r = 1", C:"H₀: intercept = 0", D:"H₀: β = 0"}, answer:"D", explanation:"The slope row's t and P-value test whether the population slope is 0." },
      { id:"u9q15", q:"A very small P-value for the slope indicates:", choices:{A:"the residuals are large", B:"r² = 0", C:"strong evidence of a linear relationship", D:"no relationship"}, answer:"C", explanation:"A small P-value rejects β = 0, supporting a linear relationship." },
      { id:"u9q16", q:"'s' in regression output (the residual standard error) measures:", choices:{A:"the correlation", B:"the slope", C:"the typical size of a residual (prediction error)", D:"the intercept"}, answer:"C", explanation:"s estimates the standard deviation of the residuals — the typical prediction error." },
      { id:"u9q17", q:"In regression output, SE(b) is found in the slope row and is used to:", choices:{A:"find the intercept", B:"compute the t statistic and the slope's confidence interval", C:"find the mean of y", D:"find r"}, answer:"B", explanation:"SE(b) feeds both t = b/SE(b) and the CI b ± t*·SE(b)." },
      { id:"u9q18", q:"With b = 4.0, SE(b) = 1.0, and t* = 2.0, a confidence interval for the slope is:", choices:{A:"(0, 8.0)", B:"(2.0, 6.0)", C:"(3.0, 5.0)", D:"(2.0, 4.0)"}, answer:"B", explanation:"b ± t*·SE(b) = 4 ± 2·1 = (2, 6)." },
      { id:"u9q19", q:"A regression slope of 0 corresponds to a correlation of:", choices:{A:"0", B:"0.5", C:"-1", D:"1"}, answer:"A", explanation:"Slope = r·(s_y/s_x); a slope of 0 means r = 0." },
      { id:"u9q20", q:"The interpretation of the slope in context is:", choices:{A:"the correlation", B:"the residual", C:"predicted change in y per one-unit increase in x", D:"the value of y when x = 0"}, answer:"C", explanation:"Slope = predicted change in the response per unit increase in the explanatory variable." },
      { id:"u9q21", q:"To generalize regression inference to a population, you need:", choices:{A:"an intercept of 0", B:"random sampling/assignment", C:"a large slope", D:"r = 1"}, answer:"B", explanation:"Randomness in data collection justifies extending conclusions to the population." },
      { id:"u9q22", q:"Which plot best checks the regression inference conditions?", choices:{A:"a two-way table", B:"a pie chart", C:"a bar chart", D:"the residual plot (and a histogram/normal plot of residuals)"}, answer:"D", explanation:"Residual plots assess linearity and equal variance; a histogram of residuals checks normality." },
      { id:"u9q23", q:"A regression t-test gives t = 0.8, P = 0.43. At α = 0.05 you:", choices:{A:"fail to reject H₀; no significant linear relationship", B:"accept Hₐ", C:"conclude causation", D:"reject H₀"}, answer:"A", explanation:"P = 0.43 > 0.05, so there is not enough evidence of a linear relationship." },
      { id:"u9q24", q:"The width of a slope confidence interval decreases when:", choices:{A:"residual spread increases", B:"the confidence level increases", C:"the sample size increases", D:"x has little spread"}, answer:"C", explanation:"More data reduces SE(b), narrowing the interval." },
      { id:"u9q25", q:"Confidence interval for slope excludes 0 ⇔ the slope test at the matching level:", choices:{A:"is invalid", B:"rejects H₀: β = 0", C:"needs a z-test", D:"fails to reject H₀"}, answer:"B", explanation:"Excluding 0 from the CI is equivalent to rejecting β = 0 at that significance level." },
      { id:"u9q26", q:"A scatterplot with a clear curve means slope inference is:", choices:{A:"exact", B:"always valid", C:"more powerful", D:"not appropriate without transforming the data"}, answer:"D", explanation:"Nonlinearity violates the Linear condition; transform the data before inference." },
      { id:"u9q27", q:"The standard error of the slope tends to be smaller when:", choices:{A:"x has little variability", B:"the x-values are more spread out", C:"the sample is tiny", D:"residuals are large"}, answer:"B", explanation:"Greater spread in x (and smaller residual scatter, larger n) reduces SE(b)." },
      { id:"u9q28", q:"'b₀' and 'b₁' in output typically denote the:", choices:{A:"intercept and slope estimates", B:"correlation and slope", C:"residual and mean", D:"two slopes"}, answer:"A", explanation:"b₀ is the estimated intercept and b₁ the estimated slope." },
      { id:"u9q29", q:"Inference about the slope assumes the mean response has what form?", choices:{A:"exponential in x", B:"a quadratic in x", C:"a linear function of x: μ_y = α + βx", D:"constant for all x"}, answer:"C", explanation:"The model assumes the true mean of y is linear in x: μ_y = α + βx." },
      { id:"u9q30", q:"A 99% slope CI compared with a 95% one (same data) is:", choices:{A:"centered at 0", B:"the same", C:"narrower", D:"wider"}, answer:"D", explanation:"Higher confidence uses a larger t*, widening the interval." },
      { id:"u9q31", q:"Which is the response (dependent) variable in regression inference?", choices:{A:"the slope", B:"x", C:"the residual", D:"y"}, answer:"D", explanation:"y is the response; x is the explanatory variable." },
      { id:"u9q32", q:"A regression gives b = -3.0 and SE(b) = 1.5. The t statistic is:", choices:{A:"-4.5", B:"2.0", C:"-0.5", D:"-2.0"}, answer:"D", explanation:"t = -3.0/1.5 = -2.0." },
      { id:"u9q33", q:"A residual plot that fans out (spreads more as x increases) violates which condition?", choices:{A:"Linearity", B:"Independence", C:"Randomness", D:"Equal variance"}, answer:"D", explanation:"Increasing spread (a fan shape) signals non-constant variance — the Equal-variance condition fails." },
      { id:"u9q34", q:"The point estimate for the population slope β is:", choices:{A:"the sample slope b", B:"s", C:"r", D:"the intercept"}, answer:"A", explanation:"The least-squares slope b estimates the population slope β." },
      { id:"u9q35", q:"A two-sided P-value for the slope is found using:", choices:{A:"a t-distribution with n - 2 df", B:"the binomial", C:"the standard normal", D:"a chi-square distribution"}, answer:"A", explanation:"Slope inference uses the t-distribution with n - 2 degrees of freedom." },
      { id:"u9q36", q:"If SE(b) is large relative to b, the t statistic is:", choices:{A:"always significant", B:"large", C:"small, giving weak evidence against H₀", D:"negative"}, answer:"C", explanation:"A big SE(b) shrinks t = b/SE(b), weakening evidence of a nonzero slope." },
      { id:"u9q37", q:"Extrapolating a regression prediction far beyond the data is risky because:", choices:{A:"the linear pattern may not hold outside the observed range", B:"the slope changes sign automatically", C:"r becomes 1", D:"residuals vanish"}, answer:"A", explanation:"There's no evidence the linear relationship continues outside the observed x-range." },
      { id:"u9q38", q:"The intercept's t-test in output checks:", choices:{A:"H₀: μ = 0", B:"H₀: slope = 0", C:"H₀: r = 0", D:"H₀: intercept (α) = 0"}, answer:"D", explanation:"The intercept row tests whether the true intercept is 0 (often not of interest)." },
      { id:"u9q39", q:"A statistically significant slope does NOT by itself establish:", choices:{A:"correlation", B:"a nonzero slope", C:"causation", D:"a linear association"}, answer:"C", explanation:"Significance shows association; causation requires a randomized experiment." },
      { id:"u9q40", q:"Which value in regression output equals the proportion of variation in y explained by x?", choices:{A:"SE(b)", B:"the t statistic", C:"r² (R-squared)", D:"the slope"}, answer:"C", explanation:"r² gives the fraction of response variation explained by the linear model." },
      { id:"u9q41", q:"To reduce the standard error of the slope, a researcher could:", choices:{A:"collect more data over a wider range of x", B:"add outliers", C:"shrink the range of x", D:"use a smaller sample"}, answer:"A", explanation:"More data and a wider x-range both lower SE(b)." },
      { id:"u9q42", q:"A regression slope CI of (0.0, 2.0) (endpoint exactly 0) is:", choices:{A:"clearly significant", B:"borderline; the test is right at the significance boundary", C:"impossible", D:"clearly nonsignificant"}, answer:"B", explanation:"If an endpoint is exactly 0, the result sits on the rejection boundary — a borderline case." },
      { id:"u9q43", q:"An influential outlier in regression can:", choices:{A:"only change r²", B:"change the df only", C:"never affect inference", D:"substantially change b and its SE, affecting inference"}, answer:"D", explanation:"Influential points can shift the slope and its standard error, distorting conclusions." },
      { id:"u9q44", q:"Which describes a correct slope interpretation for predicting weight (lb) from height (in), slope = 4.2?", choices:{A:"r = 4.2", B:"Weight is 4.2 lb", C:"Each additional inch is associated with a predicted 4.2 lb increase in weight", D:"Height causes 4.2 lb"}, answer:"C", explanation:"Slope = predicted change in y (weight) per one-unit increase in x (height)." },
      { id:"u9q45", q:"The sampling distribution of the sample slope b is approximately:", choices:{A:"uniform", B:"t-distributed (normal-based) when conditions hold", C:"binomial", D:"chi-square"}, answer:"B", explanation:"Under the LINER conditions, b's standardized value follows a t-distribution." },
      { id:"u9q46", q:"If the residual plot shows random scatter and the histogram of residuals is roughly normal, then:", choices:{A:"the conditions for slope inference appear satisfied", B:"the slope is 0", C:"the data are categorical", D:"r² = 1"}, answer:"A", explanation:"Random residuals and approximately normal residuals support the inference conditions." },
      { id:"u9q47", q:"A larger sample size in regression inference generally:", choices:{A:"decreases power", B:"has no effect", C:"raises SE(b)", D:"increases power to detect a nonzero slope"}, answer:"D", explanation:"More data lowers SE(b), raising the power to detect a real linear relationship." },
      { id:"u9q48", q:"In the model μ_y = α + βx, β represents:", choices:{A:"the true change in mean y per unit x", B:"the y-intercept", C:"the residual standard deviation", D:"the correlation"}, answer:"A", explanation:"β is the population slope: the change in the mean response per unit increase in x." },
      { id:"u9q49", q:"Which output quantity would you use directly to build a slope confidence interval?", choices:{A:"the intercept's P-value", B:"b and SE(b)", C:"the mean of y", D:"r only"}, answer:"B", explanation:"The CI uses the slope estimate b and its standard error SE(b)." },
      { id:"u9q50", q:"Overall, inference for slopes lets us decide whether:", choices:{A:"a distribution fits a model", B:"two proportions differ", C:"two means are equal", D:"the apparent linear relationship in the sample reflects a real one in the population"}, answer:"D", explanation:"Slope inference judges whether the sample's linear trend generalizes to the population (β ≠ 0)." },
    ]
  }
];